/* Series glossary schema v1: ko, en, abbr, def, chapters[]; optional category, related, audio, examples, stage.
   This is the source of truth for both the glossary page and prose tooltips. */
window.BOOK_GLOSSARY = {
  version: 1,
  terms: [
    {"ko":"파워트레인","en":"Powertrain","abbr":"","def":"동력을 만들어 바퀴까지 전달하는 장치의 총칭. 엔진 또는 모터, 변속기, 구동축, 디퍼렌셜을 포함한다.","chapters":["overview"]},
    {"ko":"섀시","en":"Chassis","abbr":"","def":"차를 달리고 돌고 서게 하는 하부 장치의 총칭. 서스펜션, 조향, 브레이크, 휠과 타이어가 여기에 속한다.","chapters":["overview"]},
    {"ko":"전륜구동","en":"Front-engine, front-wheel drive","abbr":"FF","def":"엔진을 앞에 두고 앞바퀴를 굴리는 방식. 구동계가 앞에 모여 실내가 넓고 가벼우며 대부분의 소형·중형 승용차가 쓴다.","chapters":["overview"]},
    {"ko":"후륜구동","en":"Front-engine, rear-wheel drive","abbr":"FR","def":"엔진을 앞에 두고 프로펠러 샤프트로 뒷바퀴를 굴리는 방식. 조향과 구동을 앞뒤로 나눠 맡아 전후 무게 배분과 가속 시 접지에 유리하다.","chapters":["overview"]},
    {"ko":"미드십","en":"Mid-engine, rear-wheel drive","abbr":"MR","def":"엔진을 앞뒤 차축 사이에 두고 뒷바퀴를 굴리는 방식. 무거운 부품이 중심에 모여 요 관성 모멘트가 작아 회두가 빠르다.","chapters":["overview"]},
    {"ko":"리어 엔진 후륜구동","en":"Rear-engine, rear-wheel drive","abbr":"RR","def":"엔진을 뒤 차축 뒤쪽에 두고 뒷바퀴를 굴리는 방식. 구동 바퀴 하중이 커 발진 접지가 좋지만 뒤가 무거워 한계 거동이 까다롭다.","chapters":["overview"]},
    {"ko":"사륜구동","en":"All-wheel drive","abbr":"AWD / 4WD","def":"네 바퀴 모두에 구동력을 전달하는 방식. 구동력을 네 접지면에 나눠 미끄러운 노면과 급가속에서 유리하다.","chapters":["overview"]},
    {"ko":"휠베이스","en":"Wheelbase","abbr":"","def":"앞 차축 중심과 뒤 차축 중심 사이의 거리(축거). 길수록 직진 안정성과 실내 공간이 좋아지고 회전 반경은 커진다.","chapters":["overview"]},
    {"ko":"윤거","en":"Track width","abbr":"","def":"같은 차축의 좌우 바퀴 중심 사이 거리. 트레드라고도 부르며, 넓을수록 선회 시 좌우 하중 이동이 줄어든다.","chapters":["overview"]},
    {"ko":"오버행","en":"Overhang","abbr":"","def":"차축 중심에서 차체 앞끝(또는 뒤끝)까지 튀어나온 길이. 짧을수록 접근각이 커지고 요 관성이 줄어든다.","chapters":["overview"]},
    {"ko":"공차 중량","en":"Curb weight","abbr":"","def":"연료와 냉각수 등 운행에 필요한 액체를 채우고 사람과 짐은 싣지 않은 상태의 차 무게.","chapters":["overview"]},
    {"ko":"차량 총중량","en":"Gross vehicle weight","abbr":"GVW","def":"공차 중량에 정원과 최대 적재량을 더한 무게. 브레이크와 서스펜션 설계의 기준이 된다.","chapters":["overview"]},
    {"ko":"무게 배분","en":"Weight distribution","abbr":"","def":"정지 상태에서 앞 차축과 뒤 차축이 지는 하중의 비율. FF 승용차는 대표적으로 약 60:40, FR 스포츠카는 50:50에 가깝다.","chapters":["overview"]},
    {"ko":"무게중심 높이","en":"Center of gravity height","abbr":"CG","def":"지면에서 차 전체 무게중심까지의 높이. 낮을수록 가감속과 선회 때의 하중 이동과 롤이 줄어든다.","chapters":["overview"]},
    {"ko":"주행 저항","en":"Road load","abbr":"","def":"차가 달릴 때 진행을 막는 힘의 합. 구름 저항, 공기 저항, 등판 저항, 가속 저항으로 나눈다.","chapters":["dynamics"]},
    {"ko":"구름 저항","en":"Rolling resistance","abbr":"","def":"타이어가 구르며 변형과 복원을 반복할 때 고무의 히스테리시스로 잃는 에너지에서 생기는 저항. 크기는 대략 구름 저항 계수 × 수직 하중이다.","chapters":["dynamics"]},
    {"ko":"구름 저항 계수","en":"Rolling resistance coefficient","abbr":"Crr","def":"구름 저항을 수직 하중으로 나눈 무차원 값. 승용차 타이어는 대표적으로 약 0.008~0.015다.","chapters":["dynamics"]},
    {"ko":"공기 저항","en":"Aerodynamic drag","abbr":"","def":"공기를 밀어내며 생기는 저항으로 ½ρ·Cd·A·v²이다. 속도의 제곱에 비례하므로 고속에서는 주행 저항의 대부분을 차지한다.","chapters":["dynamics"]},
    {"ko":"등판 저항","en":"Grade resistance","abbr":"","def":"경사로에서 중력의 경사 방향 성분 m·g·sinθ가 만드는 저항. 내리막에서는 음수가 되어 차를 민다.","chapters":["dynamics"]},
    {"ko":"가속 저항","en":"Inertial resistance","abbr":"","def":"속도를 바꿀 때 관성 때문에 필요한 힘. 바퀴와 구동계의 회전 관성까지 포함하려면 질량에 회전 질량 환산 계수를 곱한다.","chapters":["dynamics"]},
    {"ko":"구동력","en":"Tractive force","abbr":"","def":"구동 바퀴가 접지면에서 노면을 뒤로 밀어 얻는 추진력. 구동축 토크를 타이어 동하중 반경으로 나눈 값이며 타이어 마찰 한계를 넘을 수 없다.","chapters":["dynamics"]},
    {"ko":"구동력 선도","en":"Tractive force diagram","abbr":"","def":"각 변속단의 구동력과 주행 저항을 차속에 대해 그린 그래프. 두 곡선의 차가 여유 구동력이고 교점이 최고 속도다.","chapters":["dynamics"]},
    {"ko":"여유 구동력","en":"Excess tractive force","abbr":"","def":"구동력에서 주행 저항을 뺀 값. 가속과 등판에 쓸 수 있는 힘으로, 0이 되는 속도가 최고 속도다.","chapters":["dynamics"]},
    {"ko":"타력 주행","en":"Coasting / coast-down","abbr":"","def":"동력을 끊고 관성으로만 달리는 것. 속도가 줄어드는 곡선을 측정하면 구름 저항과 공기 저항을 분리해 구할 수 있다.","chapters":["dynamics"]},
    {"ko":"출력 대 중량비","en":"Power-to-weight ratio","abbr":"","def":"최고 출력을 차 무게로 나눈 값. 가속 성능을 가늠하는 가장 간단한 지표다.","chapters":["dynamics"]},
    {"ko":"4행정 사이클","en":"Four-stroke cycle","abbr":"","def":"흡입·압축·폭발(팽창)·배기의 네 행정으로 한 번의 일을 하는 사이클. 크랭크축이 2회전(720°)하는 동안 한 번 폭발한다.","chapters":["engine"]},
    {"ko":"상사점","en":"Top dead center","abbr":"TDC","def":"피스톤이 실린더 안에서 가장 높이 올라간 위치. 이때 연소실 체적이 최소다.","chapters":["engine"]},
    {"ko":"하사점","en":"Bottom dead center","abbr":"BDC","def":"피스톤이 가장 낮게 내려간 위치. 상사점과 하사점 사이의 거리가 스트로크다.","chapters":["engine"]},
    {"ko":"배기량","en":"Displacement","abbr":"","def":"피스톤이 하사점에서 상사점까지 쓸고 지나가는 체적에 기통 수를 곱한 값. π/4·보어²·스트로크·기통 수로 계산한다.","chapters":["engine"]},
    {"ko":"보어와 스트로크","en":"Bore and stroke","abbr":"","def":"실린더 안지름과 피스톤 행정 길이. 보어가 스트로크보다 큰 쇼트 스트로크는 고회전에, 반대인 롱 스트로크는 저속 토크와 열효율에 유리하다.","chapters":["engine"]},
    {"ko":"압축비","en":"Compression ratio","abbr":"r","def":"하사점 때의 실린더 체적을 상사점 때의 체적으로 나눈 값. 높을수록 이론 열효율이 오르지만 가솔린 엔진에서는 노킹이 한계를 만든다.","chapters":["engine"]},
    {"ko":"오토 사이클","en":"Otto cycle","abbr":"","def":"가솔린 엔진의 이상 사이클로 단열 압축, 정적 가열, 단열 팽창, 정적 방열로 이루어진다. 열효율은 1 − 1/r^(γ−1)이다.","chapters":["engine"]},
    {"ko":"P–V 선도","en":"P–V diagram","abbr":"","def":"실린더 압력과 체적의 관계를 그린 그래프. 루프가 둘러싼 넓이가 한 사이클 동안 가스가 피스톤에 한 일(지시 일)이다.","chapters":["engine"]},
    {"ko":"평균 유효 압력","en":"Brake mean effective pressure","abbr":"BMEP","def":"한 사이클의 축 일을 배기량으로 나눈 가상의 평균 압력. 배기량과 무관하게 엔진의 부하 수준을 비교하는 척도다.","chapters":["engine"]},
    {"ko":"토크","en":"Torque","abbr":"T","def":"축을 돌리려는 힘의 모멘트(N·m). 엔진 토크는 한 사이클에 하는 일의 크기에 비례한다.","chapters":["engine"]},
    {"ko":"출력","en":"Power","abbr":"P","def":"단위 시간에 하는 일로 토크 × 각속도다. 같은 토크라도 회전수가 높으면 출력이 커지므로, 가속 성능은 결국 바퀴에 전달되는 출력이 정한다.","chapters":["engine"]},
    {"ko":"체적 효율","en":"Volumetric efficiency","abbr":"ηv","def":"한 사이클에 실제로 들어온 공기량을 배기량만큼의 대기 상태 공기량으로 나눈 비율. 토크 곡선의 모양을 좌우한다.","chapters":["engine"]},
    {"ko":"크랭크샤프트","en":"Crankshaft","abbr":"","def":"피스톤의 왕복 운동을 커넥팅 로드를 거쳐 회전 운동으로 바꾸는 축.","chapters":["engine"]},
    {"ko":"커넥팅 로드","en":"Connecting rod","abbr":"","def":"피스톤과 크랭크 핀을 잇는 막대. 길이와 크랭크 반경의 비가 피스톤 가속도와 측압을 정한다.","chapters":["engine"]},
    {"ko":"플라이휠","en":"Flywheel","abbr":"","def":"크랭크축 끝에 달린 무거운 원판. 회전 관성으로 폭발 행정 사이의 토크 맥동을 흡수해 회전을 고르게 한다.","chapters":["engine"]},
    {"ko":"캠샤프트","en":"Camshaft","abbr":"","def":"캠으로 흡기·배기 밸브를 여닫는 축. 4행정 엔진에서는 크랭크축의 절반 속도로 돈다.","chapters":["engine"]},
    {"ko":"DOHC","en":"Double overhead camshaft","abbr":"DOHC","def":"실린더 헤드 위에 흡기용과 배기용 캠축을 따로 둔 밸브 구동 방식. 기통당 4밸브 배치와 가변 밸브 타이밍에 유리하다.","chapters":["engine"]},
    {"ko":"가변 밸브 타이밍","en":"Variable valve timing","abbr":"VVT","def":"운전 조건에 따라 밸브가 열리고 닫히는 시기를 바꾸는 장치. 저속 토크와 고속 출력, 연비와 배출가스를 함께 개선한다.","chapters":["engine"]},
    {"ko":"밸브 오버랩","en":"Valve overlap","abbr":"","def":"배기 행정 끝과 흡입 행정 처음에 흡기·배기 밸브가 동시에 열려 있는 구간. 고회전에서 소기를 돕지만 저회전에서는 잔류 가스가 늘어난다.","chapters":["engine"]},
    {"ko":"점화 순서","en":"Firing order","abbr":"","def":"다기통 엔진에서 실린더가 폭발하는 차례. 직렬 4기통은 1-3-4-2가 대표적이며 진동과 토크 맥동이 고르게 되도록 정한다.","chapters":["engine"]},
    {"ko":"압축 착화","en":"Compression ignition","abbr":"CI","def":"공기만 높은 압축비로 압축해 뜨거워진 곳에 연료를 분사해 스스로 불붙게 하는 방식. 디젤 엔진의 원리다.","chapters":["engine"]},
    {"ko":"공연비","en":"Air–fuel ratio","abbr":"AFR","def":"혼합기 속 공기 질량과 연료 질량의 비. 가솔린의 이론 공연비는 약 14.7:1이다.","chapters":["combustion"]},
    {"ko":"람다","en":"Lambda (excess air ratio)","abbr":"λ","def":"실제 공연비를 이론 공연비로 나눈 값. 1이면 이론 혼합, 1보다 작으면 농후, 크면 희박이다.","chapters":["combustion"]},
    {"ko":"직분사","en":"Gasoline direct injection","abbr":"GDI","def":"연료를 흡기 포트가 아니라 실린더 안에 고압으로 직접 뿌리는 방식. 기화열로 충전 공기를 식혀 노킹 여유와 체적 효율이 좋아진다.","chapters":["combustion"]},
    {"ko":"포트 분사","en":"Port fuel injection","abbr":"PFI / MPI","def":"흡기 밸브 앞 흡기 포트에 연료를 분사하는 방식. 구조가 단순하고 혼합이 잘 되며 미세 입자 배출이 적다.","chapters":["combustion"]},
    {"ko":"스로틀","en":"Throttle","abbr":"","def":"흡기 통로의 나비 밸브. 가솔린 엔진은 이것으로 들어오는 공기량을 조절해 출력을 제어하며, 부분 부하에서 펌핑 손실의 원인이 된다.","chapters":["combustion"]},
    {"ko":"점화 진각","en":"Ignition advance","abbr":"","def":"피스톤이 상사점에 오기 전에 미리 점화하는 각도. 연소에 시간이 걸리므로 회전수가 높을수록 더 일찍 점화해야 한다.","chapters":["combustion"]},
    {"ko":"MBT","en":"Minimum advance for best torque","abbr":"MBT","def":"최대 토크를 내는 최소 점화 진각. 노킹 때문에 이보다 늦게 점화해야 하면 토크와 효율을 잃는다.","chapters":["combustion"]},
    {"ko":"노킹","en":"Knock","abbr":"","def":"화염이 닿기 전에 남은 혼합기가 스스로 폭발해 압력파가 실린더를 때리는 이상 연소. 압축비와 과급압, 점화 진각의 한계를 정한다.","chapters":["combustion"]},
    {"ko":"옥탄가","en":"Octane number","abbr":"RON","def":"연료가 자기 착화에 저항하는 정도를 나타내는 지수. 높을수록 노킹이 덜 일어나 높은 압축비를 쓸 수 있다.","chapters":["combustion"]},
    {"ko":"터보차저","en":"Turbocharger","abbr":"","def":"배기가스 에너지로 터빈을 돌리고 같은 축의 압축기로 흡기를 압축하는 과급기. 같은 배기량에서 더 많은 공기를 넣어 토크를 키운다.","chapters":["combustion"]},
    {"ko":"웨이스트게이트","en":"Wastegate","abbr":"","def":"배기가스 일부를 터빈을 거치지 않고 우회시키는 밸브. 과급압이 목표를 넘지 않게 제한한다.","chapters":["combustion"]},
    {"ko":"인터쿨러","en":"Intercooler","abbr":"","def":"압축되며 뜨거워진 흡기를 식히는 열교환기. 공기 밀도를 높이고 노킹을 줄인다.","chapters":["combustion"]},
    {"ko":"삼원 촉매","en":"Three-way catalyst","abbr":"TWC","def":"CO와 HC는 산화시키고 NOx는 환원시켜 세 가지를 한 번에 정화하는 촉매. 람다 1 부근의 좁은 창에서만 세 성분 모두 높은 정화율을 낸다.","chapters":["combustion"]},
    {"ko":"산소 센서","en":"Oxygen (lambda) sensor","abbr":"","def":"배기가스 속 잔류 산소로 혼합기가 농후한지 희박한지 알려 주는 센서. 공연비 피드백 제어의 눈이다.","chapters":["combustion"]},
    {"ko":"배기가스 재순환","en":"Exhaust gas recirculation","abbr":"EGR","def":"배기가스 일부를 흡기로 되돌려 연소 온도를 낮추는 장치. NOx를 줄이고 부분 부하의 펌핑 손실도 줄인다.","chapters":["combustion"]},
    {"ko":"디젤 미립자 필터","en":"Diesel particulate filter","abbr":"DPF","def":"디젤 배기의 매연 입자를 걸러 모았다가 주기적으로 태워 없애는(재생) 필터.","chapters":["combustion"]},
    {"ko":"가솔린 미립자 필터","en":"Gasoline particulate filter","abbr":"GPF","def":"직분사 가솔린 엔진의 미세 입자를 거르는 필터. 원리는 DPF와 같다.","chapters":["combustion"]},
    {"ko":"선택적 촉매 환원","en":"Selective catalytic reduction","abbr":"SCR","def":"요소수에서 나온 암모니아로 NOx를 질소와 물로 환원하는 장치. 희박 연소라 삼원 촉매를 쓸 수 없는 디젤에 쓴다.","chapters":["combustion"]},
    {"ko":"제동 연료 소비율","en":"Brake specific fuel consumption","abbr":"BSFC","def":"축 출력 1 kWh를 내는 데 쓰는 연료량(g/kWh). 작을수록 효율이 좋으며, 회전수–토크 평면에 그린 등고선이 BSFC 맵이다.","chapters":["combustion"]},
    {"ko":"펌핑 손실","en":"Pumping loss","abbr":"","def":"흡기를 빨아들이고 배기를 밀어내는 데 드는 일. 스로틀을 조금만 연 부분 부하에서 커져 가솔린 엔진의 저부하 효율을 떨어뜨린다.","chapters":["combustion"]},
    {"ko":"기어비","en":"Gear ratio","abbr":"","def":"입력축 회전수를 출력축 회전수로 나눈 값으로 맞물린 기어의 잇수비와 같다. 기어비만큼 토크는 커지고 회전수는 줄어든다.","chapters":["transmission"]},
    {"ko":"종감속비","en":"Final drive ratio","abbr":"","def":"변속기 출력과 구동 바퀴 사이에서 마지막으로 한 번 더 감속하는 비. 전체 감속비는 변속단 기어비 × 종감속비다.","chapters":["transmission"]},
    {"ko":"클러치","en":"Clutch","abbr":"","def":"마찰판을 눌러 붙이거나 떼어 엔진과 변속기 사이의 동력을 잇고 끊는 장치. 전달 가능 토크는 마찰 계수 × 누르는 힘 × 유효 반경 × 마찰면 수다.","chapters":["transmission"]},
    {"ko":"반클러치","en":"Clutch slip (partial engagement)","abbr":"","def":"클러치를 미끄러뜨리며 일부 토크만 전달하는 상태. 정지한 차를 부드럽게 출발시키지만 속도 차만큼의 일이 열로 버려진다.","chapters":["transmission"]},
    {"ko":"수동 변속기","en":"Manual transmission","abbr":"MT","def":"운전자가 클러치와 변속 레버로 기어를 고르는 변속기. 기어 쌍은 늘 맞물려 있고 슬리브가 어느 기어를 출력축에 고정할지 정한다.","chapters":["transmission"]},
    {"ko":"싱크로나이저","en":"Synchronizer","abbr":"","def":"기어를 물리기 전에 원뿔 마찰면으로 두 부품의 회전 속도를 맞춰 주는 장치. 덕분에 기어가 갈리지 않고 들어간다.","chapters":["transmission"]},
    {"ko":"도그 클러치","en":"Dog clutch","abbr":"","def":"마찰이 아니라 이와 홈이 맞물려 동력을 전달하는 클러치. 미끄러짐이 없어 속도가 맞은 뒤에만 물릴 수 있다.","chapters":["transmission"]},
    {"ko":"토크 컨버터","en":"Torque converter","abbr":"","def":"펌프·터빈·스테이터 사이를 도는 오일로 동력을 전달하는 유체 커플링. 속도 차가 클 때 토크를 증배해 부드럽게 출발시킨다.","chapters":["transmission"]},
    {"ko":"록업 클러치","en":"Lock-up clutch","abbr":"","def":"토크 컨버터의 입력과 출력을 기계적으로 직결하는 클러치. 유체 미끄러짐 손실을 없애 연비를 높인다.","chapters":["transmission"]},
    {"ko":"유성 기어","en":"Planetary gear set","abbr":"","def":"선 기어, 유성 기어를 든 캐리어, 링 기어로 이루어진 기어 세트. 어느 요소를 고정하고 어느 것을 입력으로 쓰느냐에 따라 여러 기어비가 나온다.","chapters":["transmission"]},
    {"ko":"윌리스 식","en":"Willis equation","abbr":"","def":"유성 기어 세 요소의 회전 속도 관계식. 선 기어 속도 + (링 잇수/선 잇수) × 링 속도 = (1 + 링 잇수/선 잇수) × 캐리어 속도.","chapters":["transmission"]},
    {"ko":"자동 변속기","en":"Automatic transmission","abbr":"AT","def":"토크 컨버터와 여러 개의 유성 기어 세트, 습식 다판 클러치·브레이크로 변속을 자동으로 하는 변속기.","chapters":["transmission"]},
    {"ko":"듀얼 클러치 변속기","en":"Dual-clutch transmission","abbr":"DCT","def":"홀수단과 짝수단을 각각 맡는 두 개의 클러치를 가진 변속기. 다음 단을 미리 물려 두고 클러치만 바꿔 물어 동력 끊김이 거의 없다.","chapters":["transmission"]},
    {"ko":"무단 변속기","en":"Continuously variable transmission","abbr":"CVT","def":"폭이 변하는 두 풀리와 벨트로 변속비를 연속적으로 바꾸는 변속기. 엔진을 효율 좋은 회전수에 둔 채 가속할 수 있다.","chapters":["transmission"]},
    {"ko":"변속 선도","en":"Shift map","abbr":"","def":"스로틀 개도와 차속 평면에 변속 시점을 그린 지도. 업시프트와 다운시프트 선을 떨어뜨려(히스테리시스) 잦은 변속을 막는다.","chapters":["transmission"]},
    {"ko":"톱니 선도","en":"Sawtooth diagram","abbr":"","def":"차속에 대한 각 단의 엔진 회전수를 그린 그래프. 변속할 때마다 회전수가 떨어지는 모양이 톱니처럼 보인다.","chapters":["transmission"]},
    {"ko":"프로펠러 샤프트","en":"Propeller shaft","abbr":"","def":"앞쪽 변속기에서 뒤 차축의 디퍼렌셜까지 동력을 전달하는 긴 축. FR과 AWD 차에 있다.","chapters":["driveline"]},
    {"ko":"드라이브 샤프트","en":"Drive shaft (half shaft)","abbr":"","def":"디퍼렌셜에서 좌우 구동 바퀴까지 동력을 전달하는 축. 서스펜션과 조향의 움직임을 받아 주도록 양끝에 등속 조인트가 달린다.","chapters":["driveline"]},
    {"ko":"유니버설 조인트","en":"Universal joint","abbr":"U-joint","def":"십자축으로 두 축을 꺾어 잇는 조인트. 꺾임각이 있으면 출력 회전 속도가 한 바퀴에 두 번 출렁이므로 보통 두 개를 짝지어 상쇄한다.","chapters":["driveline"]},
    {"ko":"등속 조인트","en":"Constant-velocity joint","abbr":"CV joint","def":"꺾임각이 있어도 입력과 출력의 회전 속도가 항상 같은 조인트. 조향되는 구동 바퀴에 필수다.","chapters":["driveline"]},
    {"ko":"디퍼렌셜","en":"Differential","abbr":"","def":"선회할 때 좌우 바퀴가 서로 다른 속도로 돌 수 있게 하면서 구동 토크를 나누는 기어 장치. 두 바퀴 속도의 평균이 링 기어 속도와 같다.","chapters":["driveline"]},
    {"ko":"오픈 디퍼렌셜","en":"Open differential","abbr":"","def":"차동 제한이 없는 기본 디퍼렌셜. 좌우에 항상 같은 토크를 보내므로 한쪽 바퀴가 헛돌면 반대쪽도 그만큼밖에 힘을 받지 못한다.","chapters":["driveline"]},
    {"ko":"차동 제한 장치","en":"Limited-slip differential","abbr":"LSD","def":"좌우 바퀴의 회전 차를 마찰 등으로 제한해 접지가 좋은 쪽에 더 많은 토크를 보내는 디퍼렌셜.","chapters":["driveline"]},
    {"ko":"토르센","en":"Torsen (torque-sensing) differential","abbr":"","def":"웜 기어의 마찰 특성을 이용해 토크 차에 반응하는 기계식 LSD. 토크 바이어스비 한도 안에서 느린 쪽으로 토크를 더 보낸다.","chapters":["driveline"]},
    {"ko":"토크 벡터링","en":"Torque vectoring","abbr":"","def":"좌우 바퀴의 구동력(또는 제동력)을 능동적으로 다르게 주어 요 모멘트를 만드는 기술. 선회 진입을 돕고 언더스티어를 줄인다.","chapters":["driveline"]},
    {"ko":"트랜스퍼 케이스","en":"Transfer case","abbr":"","def":"변속기 출력을 앞 차축과 뒤 차축으로 나누는 장치. 센터 디퍼렌셜이나 다판 클러치로 전후 배분을 정한다.","chapters":["driveline"]},
    {"ko":"센터 디퍼렌셜","en":"Center differential","abbr":"","def":"상시 사륜구동에서 앞 차축과 뒤 차축의 회전 차를 허용하는 디퍼렌셜. 없으면 선회 때 구동계가 비틀린다.","chapters":["driveline"]},
    {"ko":"e-액슬","en":"e-Axle","abbr":"","def":"모터, 인버터, 감속기와 디퍼렌셜을 한 덩어리로 묶은 전기 구동 차축. 프로펠러 샤프트 없이 차축마다 독립으로 달 수 있다.","chapters":["driveline"]},
    {"ko":"접지면","en":"Contact patch","abbr":"","def":"타이어가 노면에 닿는 면. 승용차는 한 바퀴에 엽서 한 장 정도 크기이며 면적은 대략 하중 ÷ 공기압이다.","chapters":["tire"]},
    {"ko":"트레드","en":"Tread","abbr":"","def":"노면과 직접 닿는 타이어 바깥 고무층. 홈(그루브)이 물을 빼내 젖은 길 접지를 지킨다.","chapters":["tire"]},
    {"ko":"사이드월","en":"Sidewall","abbr":"","def":"트레드와 비드 사이의 타이어 옆면. 하중을 받아 휘며 승차감과 횡 강성에 영향을 준다.","chapters":["tire"]},
    {"ko":"카커스","en":"Carcass","abbr":"","def":"타이어의 뼈대가 되는 코드층. 공기압을 버텨 형상을 유지하며, 코드가 반지름 방향으로 놓인 것이 래디얼 타이어다.","chapters":["tire"]},
    {"ko":"편평비","en":"Aspect ratio","abbr":"","def":"타이어 단면 높이를 단면 폭으로 나눈 백분율. 205/55R16의 55가 편평비다.","chapters":["tire"]},
    {"ko":"슬립률","en":"Slip ratio","abbr":"κ","def":"바퀴 원주 속도와 차속의 차이를 비율로 나타낸 값. 0은 순수 구름, 제동 시 100 %는 완전 잠김이며 마찰력은 보통 10~20 % 부근에서 최대가 된다.","chapters":["tire"]},
    {"ko":"슬립각","en":"Slip angle","abbr":"α","def":"바퀴가 향한 방향과 바퀴가 실제로 나아가는 방향 사이의 각. 이 각이 있어야 타이어가 횡력을 낸다.","chapters":["tire"]},
    {"ko":"코너링 강성","en":"Cornering stiffness","abbr":"Cα","def":"작은 슬립각에서 슬립각 1단위당 생기는 횡력. 횡력–슬립각 곡선의 원점 기울기다.","chapters":["tire"]},
    {"ko":"마찰원","en":"Friction circle","abbr":"","def":"타이어가 낼 수 있는 종력과 횡력의 합력 한계를 나타낸 원. 반지름은 마찰 계수 × 수직 하중이며 제동에 그립을 쓰면 선회에 쓸 몫이 줄어든다.","chapters":["tire"]},
    {"ko":"매직 포뮬러","en":"Pacejka Magic Formula","abbr":"","def":"타이어의 힘–슬립 곡선을 D·sin(C·arctan(B·x − E·(B·x − arctan(B·x)))) 꼴로 맞춘 경험식. 차량 동역학 시뮬레이션의 표준 타이어 모델이다.","chapters":["tire"]},
    {"ko":"브러시 모델","en":"Brush model","abbr":"","def":"트레드를 노면에 붙은 수많은 솔(강모)로 본 물리 모델. 접지면 앞쪽은 점착, 뒤쪽은 미끄럼 영역으로 나뉘는 것을 설명한다.","chapters":["tire"]},
    {"ko":"하중 민감도","en":"Load sensitivity","abbr":"","def":"수직 하중이 커질수록 타이어의 유효 마찰 계수가 조금씩 줄어드는 성질. 그래서 하중 이동이 클수록 좌우 타이어의 그립 합이 줄어든다.","chapters":["tire"]},
    {"ko":"하중 이동","en":"Load transfer","abbr":"","def":"가감속이나 선회 때 관성력이 무게중심에 걸려 바퀴 사이의 수직 하중이 옮겨 가는 현상. 크기는 무게중심 높이에 비례하고 휠베이스나 윤거에 반비례한다.","chapters":["tire"]},
    {"ko":"셀프 얼라이닝 토크","en":"Self-aligning torque","abbr":"SAT","def":"슬립각이 있을 때 타이어를 진행 방향으로 되돌리려는 모멘트. 운전자가 느끼는 조향 반력의 주된 원천이다.","chapters":["tire"]},
    {"ko":"뉴매틱 트레일","en":"Pneumatic trail","abbr":"","def":"횡력의 작용점이 접지면 중심보다 뒤로 물러난 거리. 한계에 가까워지면 줄어들어 핸들이 가벼워지는 것으로 그립의 끝을 알린다.","chapters":["tire"]},
    {"ko":"캠버 스러스트","en":"Camber thrust","abbr":"","def":"바퀴가 기울어져 구를 때 기운 쪽으로 생기는 횡력. 이륜차 선회력의 주된 원천이다.","chapters":["tire"]},
    {"ko":"수막 현상","en":"Hydroplaning","abbr":"","def":"물이 미처 빠지지 못해 타이어가 수막 위에 떠 버리는 현상. 속도가 높고 트레드가 닳고 공기압이 낮을수록 잘 일어난다.","chapters":["tire"]},
    {"ko":"타이어 공기압 감시 장치","en":"Tire pressure monitoring system","abbr":"TPMS","def":"타이어 공기압을 감시해 기준 이하로 떨어지면 경고하는 장치. 휠 안의 압력 센서를 쓰는 직접식과 휠 속도 차로 추정하는 간접식이 있다.","chapters":["tire"]},
    {"ko":"마스터 실린더","en":"Master cylinder","abbr":"","def":"브레이크 페달의 힘을 유압으로 바꾸는 실린더. 한 회로가 새도 제동이 남도록 두 개의 독립 회로(탠덤)로 만든다.","chapters":["brake"]},
    {"ko":"캘리퍼","en":"Caliper","abbr":"","def":"유압 피스톤으로 패드를 디스크 양쪽에서 눌러 죄는 부품.","chapters":["brake"]},
    {"ko":"브레이크 디스크","en":"Brake disc (rotor)","abbr":"","def":"바퀴와 함께 도는 원판. 패드와의 마찰로 운동 에너지를 열로 바꾸며, 가운데 통풍 날개를 둔 벤틸레이티드 디스크가 열 방출에 유리하다.","chapters":["brake"]},
    {"ko":"브레이크 패드","en":"Brake pad","abbr":"","def":"디스크에 눌려 마찰력을 만드는 마찰재. 마찰 계수는 대표적으로 약 0.3~0.5이며 온도에 따라 변한다.","chapters":["brake"]},
    {"ko":"브레이크 부스터","en":"Brake booster","abbr":"","def":"운전자의 페달 힘을 배력하는 장치. 흡기 부압을 쓰는 진공식에서 모터로 미는 전동식으로 바뀌고 있다.","chapters":["brake"]},
    {"ko":"공주 거리","en":"Reaction distance","abbr":"","def":"위험을 알아차리고 브레이크가 실제로 듣기 시작할 때까지 차가 그대로 달리는 거리. 속도 × 반응 시간이다.","chapters":["brake"]},
    {"ko":"제동 거리","en":"Braking distance","abbr":"","def":"브레이크가 작동한 뒤 멈출 때까지 가는 거리. v²/(2·μ·g)로 속도의 제곱에 비례한다.","chapters":["brake"]},
    {"ko":"정지 거리","en":"Stopping distance","abbr":"","def":"공주 거리와 제동 거리의 합. 운전자가 위험을 본 순간부터 차가 완전히 멈출 때까지의 거리다.","chapters":["brake"]},
    {"ko":"페이드","en":"Brake fade","abbr":"","def":"브레이크가 과열되어 패드의 마찰 계수가 떨어지고 제동력이 줄어드는 현상. 긴 내리막에서 계속 밟을 때 생긴다.","chapters":["brake"]},
    {"ko":"베이퍼 록","en":"Vapor lock","abbr":"","def":"브레이크액이 끓어 생긴 기포가 압축되면서 페달을 밟아도 유압이 전달되지 않는 현상. 수분을 머금은 오래된 브레이크액일수록 끓는점이 낮다.","chapters":["brake"]},
    {"ko":"잠김 방지 브레이크","en":"Anti-lock braking system","abbr":"ABS","def":"바퀴가 잠기려 하면 유압을 빠르게 줄였다 늘려 슬립률을 마찰 피크 부근에 유지하는 장치. 급제동 중에도 조향이 가능하게 한다.","chapters":["brake"]},
    {"ko":"전자식 제동력 배분","en":"Electronic brakeforce distribution","abbr":"EBD","def":"적재 상태와 감속도에 맞춰 앞뒤 제동력 비율을 전자적으로 조절하는 기능. 뒷바퀴가 먼저 잠기는 것을 막는다.","chapters":["brake"]},
    {"ko":"제동력 배분","en":"Brake balance","abbr":"","def":"앞바퀴와 뒷바퀴가 나눠 맡는 제동력의 비율. 감속할수록 하중이 앞으로 쏠리므로 앞쪽이 더 큰 몫을 맡는다.","chapters":["brake"]},
    {"ko":"브레이크 바이 와이어","en":"Brake-by-wire","abbr":"BBW","def":"페달과 유압 발생부를 기계적으로 분리하고 전기 신호로 제동하는 방식. 회생 제동과 마찰 제동을 운전자가 모르게 섞을 수 있다.","chapters":["brake"]},
    {"ko":"스프링 상수","en":"Spring rate","abbr":"k","def":"스프링을 단위 길이만큼 변형시키는 데 필요한 힘(N/mm). 바퀴 위치에서 본 등가 값이 휠 레이트다.","chapters":["suspension"]},
    {"ko":"모션비","en":"Motion ratio","abbr":"","def":"바퀴 스트로크에 대한 스프링(댐퍼) 스트로크의 비. 휠 레이트는 스프링 상수 × 모션비²이다.","chapters":["suspension"]},
    {"ko":"댐퍼","en":"Damper (shock absorber)","abbr":"","def":"오일이 좁은 구멍을 지나는 저항으로 진동 에너지를 열로 바꾸는 장치. 감쇠력은 스트로크 속도에 따라 정해진다.","chapters":["suspension"]},
    {"ko":"스프링 위 질량","en":"Sprung mass","abbr":"","def":"스프링이 받치고 있는 차체와 탑승자, 짐의 질량.","chapters":["suspension"]},
    {"ko":"스프링 아래 질량","en":"Unsprung mass","abbr":"","def":"스프링 아래에서 노면을 직접 따라 움직이는 휠, 타이어, 브레이크, 너클 등의 질량. 가벼울수록 접지와 승차감에 유리하다.","chapters":["suspension"]},
    {"ko":"고유 진동수","en":"Natural frequency","abbr":"fn","def":"외력 없이 스스로 진동하는 주파수로 √(k/m)/2π다. 승용차 차체의 상하 고유 진동수는 대표적으로 약 1~1.5 Hz다.","chapters":["suspension"]},
    {"ko":"감쇠비","en":"Damping ratio","abbr":"ζ","def":"실제 감쇠 계수를 임계 감쇠 계수로 나눈 값. 1보다 작으면 진동하며 잦아들고, 승용차는 대표적으로 약 0.2~0.4를 쓴다.","chapters":["suspension"]},
    {"ko":"쿼터카 모델","en":"Quarter-car model","abbr":"","def":"차의 한 바퀴 몫만 떼어 스프링 위 질량, 스프링·댐퍼, 스프링 아래 질량, 타이어 강성으로 나타낸 2자유도 모델.","chapters":["suspension"]},
    {"ko":"휠 홉","en":"Wheel hop","abbr":"","def":"스프링 아래 질량이 타이어 강성 위에서 튀는 공진. 대표적으로 약 10~15 Hz이며 접지 하중을 크게 출렁이게 한다.","chapters":["suspension"]},
    {"ko":"맥퍼슨 스트럿","en":"MacPherson strut","abbr":"","def":"댐퍼와 스프링을 묶은 스트럿이 위쪽 링크 역할까지 겸하고 아래에 로어 암 하나를 둔 형식. 가볍고 공간을 덜 차지해 앞바퀴에 널리 쓴다.","chapters":["suspension"]},
    {"ko":"더블 위시본","en":"Double wishbone","abbr":"","def":"위아래 두 개의 A자 암으로 너클을 지지하는 형식. 암 길이와 각도로 캠버 변화와 롤 센터를 자유롭게 설계할 수 있다.","chapters":["suspension"]},
    {"ko":"멀티링크","en":"Multi-link","abbr":"","def":"세 개 이상의 독립된 링크로 바퀴의 움직임을 구속하는 형식. 설계 자유도가 가장 높아 승차감과 조종성을 함께 잡는다.","chapters":["suspension"]},
    {"ko":"토션빔","en":"Torsion beam","abbr":"","def":"좌우 트레일링 암을 비틀림 가능한 빔으로 이은 반독립 형식. 간단하고 싸며 짐칸이 넓어 소형 전륜구동차의 뒤에 쓴다.","chapters":["suspension"]},
    {"ko":"캠버","en":"Camber","abbr":"","def":"앞에서 봤을 때 바퀴가 수직에서 기운 각. 위쪽이 안으로 기운 것이 네거티브 캠버이며 선회 때 바깥 타이어의 접지를 돕는다.","chapters":["suspension"]},
    {"ko":"캐스터","en":"Caster","abbr":"","def":"옆에서 봤을 때 조향축이 뒤로 기운 각. 접지점이 조향축보다 뒤에 놓여 직진 복원력을 만든다.","chapters":["suspension"]},
    {"ko":"토","en":"Toe","abbr":"","def":"위에서 봤을 때 바퀴 앞쪽이 안(토인)이나 밖(토아웃)으로 향한 각. 직진 안정성과 회두성, 타이어 마모에 영향을 준다.","chapters":["suspension"]},
    {"ko":"킹핀 경사각","en":"Kingpin inclination","abbr":"KPI","def":"앞에서 봤을 때 조향축이 안쪽으로 기운 각. 조향하면 차체가 살짝 들려 복원력이 생긴다.","chapters":["suspension"]},
    {"ko":"스크럽 반경","en":"Scrub radius","abbr":"","def":"조향축의 연장선이 지면과 만나는 점과 접지면 중심 사이의 가로 거리. 제동력과 구동력이 조향에 미치는 영향을 정한다.","chapters":["suspension"]},
    {"ko":"롤 센터","en":"Roll center","abbr":"","def":"차체가 롤할 때 순간적으로 회전의 중심이 되는 점. 서스펜션 링크의 순간 중심에서 작도하며 높이가 롤 모멘트 팔 길이를 정한다.","chapters":["suspension"]},
    {"ko":"안티롤 바","en":"Anti-roll bar (stabilizer)","abbr":"","def":"좌우 서스펜션을 비틀림 막대로 이어 한쪽만 움직일 때 저항하는 부품. 롤 강성을 높이고 전후 배분으로 언더·오버스티어 성향을 조절한다.","chapters":["suspension"]},
    {"ko":"안티 다이브","en":"Anti-dive / anti-squat","abbr":"","def":"제동 시 앞이 숙여지거나(다이브) 가속 시 뒤가 주저앉는(스쿼트) 것을 링크 배치로 줄이는 지오메트리.","chapters":["suspension"]},
    {"ko":"에어 서스펜션","en":"Air suspension","abbr":"","def":"금속 스프링 대신 공기 주머니를 쓰는 서스펜션. 공기압으로 차고와 스프링 특성을 바꿀 수 있다.","chapters":["suspension"]},
    {"ko":"스카이훅 제어","en":"Skyhook control","abbr":"","def":"차체가 하늘의 고정점에 댐퍼로 매달린 것처럼 움직이도록 가변 댐퍼의 감쇠력을 조절하는 제어 방식.","chapters":["suspension"]},
    {"ko":"랙 앤 피니언","en":"Rack and pinion","abbr":"","def":"스티어링 축 끝의 피니언 기어가 직선 톱니 막대(랙)를 좌우로 미는 조향 기어. 랙의 움직임이 타이로드를 거쳐 너클을 돌린다.","chapters":["steering"]},
    {"ko":"조향 기어비","en":"Steering ratio","abbr":"","def":"스티어링 휠 회전각을 앞바퀴 조향각으로 나눈 값. 승용차는 대표적으로 약 12~18:1이다.","chapters":["steering"]},
    {"ko":"애커먼 조향","en":"Ackermann steering","abbr":"","def":"저속 선회에서 네 바퀴가 미끄러지지 않고 한 점을 중심으로 돌도록 안쪽 바퀴를 바깥쪽보다 더 많이 꺾는 기하.","chapters":["steering"]},
    {"ko":"최소 회전 반경","en":"Minimum turning radius","abbr":"","def":"핸들을 끝까지 꺾고 돌 때 바깥쪽 앞바퀴가 그리는 원의 반지름. 휠베이스가 짧고 최대 조향각이 클수록 작다.","chapters":["steering"]},
    {"ko":"내륜차","en":"Inner wheel difference","abbr":"","def":"선회할 때 안쪽 앞바퀴와 안쪽 뒷바퀴가 지나는 궤적의 반지름 차. 뒷바퀴가 더 안쪽으로 지나가므로 휠베이스가 긴 차일수록 크다.","chapters":["steering"]},
    {"ko":"전동 파워 스티어링","en":"Electric power steering","abbr":"EPS / MDPS","def":"토크 센서로 운전자의 조향 힘을 재고 모터로 보조하는 장치. 필요할 때만 전력을 쓰고 차로 유지 같은 능동 조향이 가능하다.","chapters":["steering"]},
    {"ko":"자전거 모델","en":"Bicycle (single-track) model","abbr":"","def":"좌우 바퀴를 하나로 합쳐 앞뒤 두 바퀴로 단순화한 차량 모델. 횡 운동과 요 운동을 다루며 조종 안정성 해석과 자율주행 제어의 기본이다.","chapters":["steering"]},
    {"ko":"횡가속도","en":"Lateral acceleration","abbr":"ay","def":"선회할 때 차가 받는 옆 방향 가속도로 v²/R이다. 일반 승용차의 한계는 마른 노면에서 대표적으로 약 0.8~1.0 g다.","chapters":["steering"]},
    {"ko":"요 레이트","en":"Yaw rate","abbr":"r","def":"차가 수직축을 중심으로 회전하는 각속도. 정상 선회에서는 속도 ÷ 선회 반경과 같다.","chapters":["steering"]},
    {"ko":"차체 슬립각","en":"Body sideslip angle","abbr":"β","def":"차체가 향한 방향과 무게중심이 실제로 나아가는 방향 사이의 각. 크게 벌어지면 스핀에 가까워진 것이다.","chapters":["steering"]},
    {"ko":"언더스티어","en":"Understeer","abbr":"US","def":"속도를 올릴수록 같은 반경을 돌기 위해 핸들을 더 꺾어야 하는 특성. 한계에서는 앞바퀴가 먼저 미끄러져 바깥으로 밀린다.","chapters":["steering"]},
    {"ko":"오버스티어","en":"Oversteer","abbr":"OS","def":"속도를 올릴수록 필요한 조향각이 줄어드는 특성. 한계에서는 뒷바퀴가 먼저 미끄러져 차가 안쪽으로 말려들며 돈다.","chapters":["steering"]},
    {"ko":"언더스티어 구배","en":"Understeer gradient","abbr":"K","def":"횡가속도가 늘 때 필요한 조향각이 얼마나 늘어나는지 나타내는 기울기. 조향각 = L/R + K·ay이며 양수면 언더스티어다.","chapters":["steering"]},
    {"ko":"특성 속도","en":"Characteristic speed","abbr":"","def":"언더스티어 차에서 필요한 조향각이 애커먼 조향각의 두 배가 되는 속도. 요 레이트 게인이 최대가 되는 속도이기도 하다.","chapters":["steering"]},
    {"ko":"임계 속도","en":"Critical speed","abbr":"","def":"오버스티어 차가 조향 없이도 발산하기 시작하는 속도. 이 속도를 넘으면 차는 스스로 불안정해진다.","chapters":["steering"]},
    {"ko":"카운터 스티어","en":"Countersteer","abbr":"","def":"뒤가 미끄러질 때 선회 반대 방향으로 핸들을 꺾어 자세를 바로잡는 조작.","chapters":["steering"]},
    {"ko":"차체 자세 제어","en":"Electronic stability control","abbr":"ESC","def":"조향각과 속도로 계산한 목표 요 레이트와 실제 요 레이트를 비교해, 어긋나면 개별 바퀴를 제동해 바로잡는 장치.","chapters":["steering"]},
    {"ko":"후륜 조향","en":"Rear-wheel steering","abbr":"RWS","def":"뒷바퀴도 몇 도 꺾는 장치. 저속에서는 앞과 반대로 꺾어 회전 반경을 줄이고, 고속에서는 같은 방향으로 꺾어 안정성을 높인다.","chapters":["steering"]},
    {"ko":"스티어 바이 와이어","en":"Steer-by-wire","abbr":"SbW","def":"스티어링 휠과 앞바퀴 사이의 기계적 연결을 없애고 전기 신호로 조향하는 방식. 조향 기어비를 자유롭게 바꿀 수 있지만 이중화가 필수다.","chapters":["steering"]},
    {"ko":"모노코크","en":"Monocoque (unibody)","abbr":"","def":"별도의 뼈대 없이 차체 외피와 골격이 일체로 하중을 받는 구조. 가볍고 강성이 높아 승용차의 표준이다.","chapters":["body"]},
    {"ko":"바디 온 프레임","en":"Body-on-frame","abbr":"","def":"사다리꼴 프레임 위에 차체를 얹는 구조. 무겁지만 튼튼하고 험로와 견인에 강해 픽업트럭과 일부 SUV가 쓴다.","chapters":["body"]},
    {"ko":"화이트 바디","en":"Body in white","abbr":"BIW","def":"도장과 의장 부품을 달기 전, 용접을 마친 차체 골격 상태.","chapters":["body"]},
    {"ko":"필러","en":"Pillar","abbr":"","def":"지붕을 받치는 기둥. 앞에서부터 A, B, C 필러라 부르며 B 필러는 측면 충돌에서 탑승 공간을 지키는 핵심 부재다.","chapters":["body"]},
    {"ko":"비틀림 강성","en":"Torsional stiffness","abbr":"","def":"차체를 앞뒤 축에서 반대로 비틀 때 단위 각도당 필요한 토크(N·m/deg). 높을수록 서스펜션이 설계대로 일하고 소음·진동이 줄어든다.","chapters":["body"]},
    {"ko":"핫스탬핑","en":"Hot stamping","abbr":"","def":"강판을 약 900 °C로 달궈 성형한 뒤 금형 안에서 급랭해 인장 강도 1.5 GPa급 초고강도 부품을 만드는 공법.","chapters":["body"]},
    {"ko":"기가캐스팅","en":"Gigacasting","abbr":"","def":"수십 개의 프레스·용접 부품을 초대형 알루미늄 다이캐스팅 한 덩어리로 바꾸는 공법. 부품 수와 공정이 줄지만 수리성이 과제다.","chapters":["body"]},
    {"ko":"크럼플 존","en":"Crumple zone","abbr":"","def":"충돌 때 일부러 찌그러지며 에너지를 흡수하는 차체 앞뒤 구역. 멈추는 거리를 늘려 탑승자가 받는 감속도를 낮춘다.","chapters":["body"]},
    {"ko":"세이프티 셀","en":"Safety cell","abbr":"","def":"충돌에도 변형되지 않도록 초고강도강으로 만든 탑승 공간. 찌그러지는 구역과 버티는 구역을 나누는 것이 충돌 설계의 기본이다.","chapters":["body"]},
    {"ko":"프리텐셔너","en":"Seat belt pretensioner","abbr":"","def":"충돌을 감지한 순간 화약 등으로 안전벨트를 되감아 느슨함을 없애는 장치.","chapters":["body"]},
    {"ko":"로드 리미터","en":"Load limiter","abbr":"","def":"벨트 장력이 일정 값을 넘으면 웨빙을 조금씩 풀어 주어 가슴에 걸리는 힘을 제한하는 장치.","chapters":["body"]},
    {"ko":"에어백","en":"Airbag","abbr":"","def":"충돌 후 수십 밀리초 안에 가스로 부풀어 머리와 가슴의 감속을 넓은 면적과 긴 거리로 나누는 보조 구속 장치. 안전벨트를 맨 것을 전제로 설계된다.","chapters":["body"]},
    {"ko":"머리 상해 기준","en":"Head injury criterion","abbr":"HIC","def":"머리 가속도의 크기와 지속 시간으로 계산하는 상해 지수. 가속도의 2.5제곱을 시간에 대해 적분하는 꼴이다.","chapters":["body"]},
    {"ko":"신차 안전도 평가","en":"New car assessment program","abbr":"NCAP","def":"정면·측면 충돌과 보행자 보호, 안전 보조 기능을 시험해 별점으로 공개하는 평가 제도.","chapters":["body"]},
    {"ko":"NVH","en":"Noise, vibration and harshness","abbr":"NVH","def":"소음, 진동, 거친 충격감을 묶어 부르는 말. 차체 강성과 마운트, 흡차음재가 좌우한다.","chapters":["body"]},
    {"ko":"항력 계수","en":"Drag coefficient","abbr":"Cd","def":"차체 형상이 공기 저항을 얼마나 만드는지 나타내는 무차원 수. 승용차는 대표적으로 약 0.25~0.35다.","chapters":["aero"]},
    {"ko":"전면 투영 면적","en":"Frontal area","abbr":"A","def":"차를 앞에서 본 그림자 면적. 승용차는 대표적으로 약 2.2 m²이다.","chapters":["aero"]},
    {"ko":"항력 면적","en":"Drag area","abbr":"CdA","def":"항력 계수와 전면 투영 면적의 곱. 실제 공기 저항을 정하는 값이므로 차끼리 비교할 때는 Cd보다 CdA를 봐야 한다.","chapters":["aero"]},
    {"ko":"경계층","en":"Boundary layer","abbr":"","def":"차체 표면 가까이에서 점성 때문에 공기 속도가 0에서 자유 흐름 속도까지 변하는 얇은 층.","chapters":["aero"]},
    {"ko":"박리","en":"Flow separation","abbr":"","def":"경계층이 압력 상승을 이기지 못하고 표면에서 떨어져 나가는 현상. 뒤에 저압의 후류를 만들어 압력 항력을 키운다.","chapters":["aero"]},
    {"ko":"후류","en":"Wake","abbr":"","def":"차 뒤에 생기는 소용돌이치는 저압 영역. 승용차 항력의 대부분은 앞뒤 압력 차에서 오는 압력 항력이다.","chapters":["aero"]},
    {"ko":"레이놀즈 수","en":"Reynolds number","abbr":"Re","def":"관성력과 점성력의 비를 나타내는 무차원 수. 축소 모형 풍동 시험이 실차와 같은 흐름을 재현하는지 판단하는 기준이다.","chapters":["aero"]},
    {"ko":"양력","en":"Lift","abbr":"","def":"차체 위아래의 압력 차로 차를 들어 올리는 힘. 고속에서 접지 하중을 줄여 안정성을 해친다.","chapters":["aero"]},
    {"ko":"다운포스","en":"Downforce","abbr":"","def":"음의 양력으로 차를 노면에 누르는 공기력. 질량을 늘리지 않고 타이어의 접지 하중만 키워 선회와 제동 한계를 높인다.","chapters":["aero"]},
    {"ko":"디퓨저","en":"Diffuser","abbr":"","def":"차 바닥 뒤쪽을 위로 넓혀 바닥 밑 흐름을 천천히 감속시키는 통로. 바닥 밑 압력을 낮춰 다운포스를 만든다.","chapters":["aero"]},
    {"ko":"그라운드 이펙트","en":"Ground effect","abbr":"","def":"차 바닥과 노면 사이의 좁은 틈으로 공기를 빠르게 흘려 낮은 압력을 만드는 효과.","chapters":["aero"]},
    {"ko":"캄 테일","en":"Kamm tail","abbr":"","def":"유선형 꼬리를 중간에서 수직으로 잘라 낸 뒷모양. 긴 꼬리 없이도 박리 위치를 고정해 낮은 항력을 얻는다.","chapters":["aero"]},
    {"ko":"스포일러","en":"Spoiler","abbr":"","def":"차체 위 흐름을 흐트러뜨려 양력을 줄이는 판. 날개 단면으로 직접 다운포스를 만드는 윙과 구분한다.","chapters":["aero"]},
    {"ko":"전자 제어 장치","en":"Electronic control unit","abbr":"ECU","def":"센서 값을 읽고 계산해 액추에이터를 구동하는 차량용 컴퓨터. 마이크로컨트롤러, 입력 회로, 출력 드라이버, 통신 회로로 이루어진다.","chapters":["electrical"]},
    {"ko":"알터네이터","en":"Alternator","abbr":"","def":"엔진이 벨트로 돌리는 교류 발전기. 정류기와 전압 조정기로 약 14 V의 직류를 만들어 전장품에 공급하고 12 V 배터리를 충전한다.","chapters":["electrical"]},
    {"ko":"암전류","en":"Parasitic (quiescent) current","abbr":"","def":"시동을 끈 뒤에도 흐르는 대기 전류. 대표적으로 수십 mA 수준이며 오래 세워 두면 배터리를 방전시킨다.","chapters":["electrical"]},
    {"ko":"와이어링 하네스","en":"Wiring harness","abbr":"","def":"차 전체에 전력과 신호를 나르는 전선 다발. 고급차에서는 총 길이 수 km, 무게 수십 kg에 이른다.","chapters":["electrical"]},
    {"ko":"릴레이","en":"Relay","abbr":"","def":"작은 전류로 큰 전류의 회로를 여닫는 전자기 스위치.","chapters":["electrical"]},
    {"ko":"홀 센서","en":"Hall-effect sensor","abbr":"","def":"자기장의 세기에 비례하는 전압을 내는 반도체 센서. 휠 속도, 크랭크 각, 페달 위치 측정에 쓴다.","chapters":["electrical"]},
    {"ko":"펄스 폭 변조","en":"Pulse-width modulation","abbr":"PWM","def":"스위치를 빠르게 켜고 끄며 켜진 시간의 비율(듀티)로 평균 전압이나 전류를 조절하는 방식. 솔레노이드, 모터, 인버터 구동의 기본이다.","chapters":["electrical"]},
    {"ko":"H-브리지","en":"H-bridge","abbr":"","def":"스위치 네 개를 H자로 배치해 모터에 걸리는 전압의 방향을 바꾸는 회로. 직류 모터의 정·역회전과 제동을 구현한다.","chapters":["electrical"]},
    {"ko":"PID 제어","en":"PID control","abbr":"PID","def":"오차에 비례(P), 오차의 적분(I), 오차의 미분(D)에 비례하는 세 항을 더해 조작량을 정하는 피드백 제어기.","chapters":["electrical"]},
    {"ko":"워치독","en":"Watchdog timer","abbr":"","def":"소프트웨어가 정해진 시간 안에 신호를 보내지 않으면 ECU를 재시작하는 감시 타이머.","chapters":["electrical"]},
    {"ko":"DC-DC 컨버터","en":"DC-DC converter","abbr":"LDC","def":"직류 전압을 다른 직류 전압으로 바꾸는 전력 변환기. 전기차에서는 고전압 배터리로 12 V 계통을 공급해 알터네이터를 대신한다.","chapters":["electrical"]},
    {"ko":"CAN","en":"Controller area network","abbr":"CAN","def":"꼬인 두 가닥 선의 차동 신호로 여러 ECU가 메시지를 주고받는 차량용 버스. 대표 속도는 500 kbps이며 프레임당 데이터는 최대 8바이트다.","chapters":["electrical"]},
    {"ko":"CAN FD","en":"CAN with flexible data-rate","abbr":"CAN FD","def":"데이터 구간의 비트 속도를 높이고 프레임당 데이터를 64바이트까지 늘린 CAN의 확장 규격.","chapters":["electrical"]},
    {"ko":"버스 중재","en":"Bus arbitration","abbr":"","def":"여러 노드가 동시에 보낼 때 ID를 한 비트씩 비교해 우선순위를 가리는 CAN의 규칙. 도미넌트(0)가 리세시브(1)를 이기므로 ID가 낮은 메시지가 손상 없이 이긴다.","chapters":["electrical"]},
    {"ko":"비트 스터핑","en":"Bit stuffing","abbr":"","def":"같은 값의 비트가 다섯 개 이어지면 반대 값 비트를 하나 끼워 넣는 규칙. 수신 측이 신호 모서리를 보고 클록을 다시 맞출 수 있게 한다.","chapters":["electrical"]},
    {"ko":"LIN","en":"Local interconnect network","abbr":"LIN","def":"한 가닥 선으로 마스터 하나가 여러 슬레이브를 부르는 저속·저가 버스. 창문, 시트, 와이퍼 같은 차체 전장에 쓴다.","chapters":["electrical"]},
    {"ko":"FlexRay","en":"FlexRay","abbr":"","def":"시간 분할 방식으로 전송 시각이 보장되는 10 Mbps급 이중화 버스. 섀시 제어처럼 결정성이 중요한 곳에 쓰였다.","chapters":["electrical"]},
    {"ko":"차량용 이더넷","en":"Automotive Ethernet","abbr":"","def":"꼬인 한 쌍의 선으로 100 Mbps~수 Gbps를 보내는 차량용 고속 네트워크. 카메라, 라이다와 중앙 컴퓨터를 잇는 백본이다.","chapters":["electrical"]},
    {"ko":"게이트웨이","en":"Gateway","abbr":"","def":"서로 다른 버스 사이에서 메시지를 골라 전달하고 변환하는 ECU. 외부 접속과 내부망을 가르는 보안 경계이기도 하다.","chapters":["electrical"]},
    {"ko":"OBD-II","en":"On-board diagnostics II","abbr":"OBD","def":"배출가스 관련 고장을 감시하고 표준 커넥터로 읽어 내게 한 진단 규격.","chapters":["electrical"]},
    {"ko":"고장 코드","en":"Diagnostic trouble code","abbr":"DTC","def":"ECU가 고장을 감지했을 때 저장하는 표준화된 코드. P0301처럼 계통과 내용을 문자와 숫자로 나타낸다.","chapters":["electrical"]},
    {"ko":"UDS","en":"Unified diagnostic services","abbr":"UDS","def":"ECU 진단, 데이터 읽기, 소프트웨어 재기록을 위한 표준 진단 프로토콜(ISO 14229).","chapters":["electrical"]},
    {"ko":"도메인 컨트롤러","en":"Domain controller","abbr":"","def":"파워트레인, 섀시, 차체, 인포테인먼트, ADAS처럼 기능 영역별로 여러 ECU의 일을 모은 고성능 제어기.","chapters":["electrical"]},
    {"ko":"존 아키텍처","en":"Zonal architecture","abbr":"","def":"차를 물리적 구역으로 나눠 구역마다 존 컨트롤러가 가까운 센서와 액추에이터를 맡고, 연산은 중앙 컴퓨터가 하는 구조. 배선 길이와 무게를 줄인다.","chapters":["electrical"]},
    {"ko":"소프트웨어 정의 차량","en":"Software-defined vehicle","abbr":"SDV","def":"기능의 대부분이 소프트웨어로 구현되어 출고 후에도 업데이트로 바뀌고 추가되는 차.","chapters":["electrical"]},
    {"ko":"무선 업데이트","en":"Over-the-air update","abbr":"OTA","def":"정비소에 가지 않고 무선 통신으로 차의 소프트웨어를 갱신하는 것.","chapters":["electrical"]},
    {"ko":"AUTOSAR","en":"Automotive open system architecture","abbr":"AUTOSAR","def":"ECU 소프트웨어를 응용 계층, 런타임 환경, 기본 소프트웨어로 나누어 표준화한 아키텍처. 하드웨어가 달라도 응용 소프트웨어를 다시 쓸 수 있게 한다.","chapters":["electrical"]},
    {"ko":"마일드 하이브리드","en":"Mild hybrid","abbr":"MHEV","def":"대표적으로 48 V 계통의 작은 모터로 엔진을 돕고 회생하는 하이브리드. 모터만으로 달리는 구간은 없거나 매우 짧다.","chapters":["hybrid"]},
    {"ko":"풀 하이브리드","en":"Full hybrid","abbr":"HEV","def":"모터만으로도 주행할 수 있을 만큼 모터와 배터리를 갖춘 하이브리드. 외부 충전 없이 엔진과 회생으로 배터리를 채운다.","chapters":["hybrid"]},
    {"ko":"플러그인 하이브리드","en":"Plug-in hybrid","abbr":"PHEV","def":"외부 전원으로 충전할 수 있는 큰 배터리를 가진 하이브리드. 짧은 거리는 전기로만 달리고 방전되면 일반 하이브리드처럼 달린다.","chapters":["hybrid"]},
    {"ko":"주행거리 연장형 전기차","en":"Extended-range electric vehicle","abbr":"EREV","def":"바퀴는 항상 모터로 굴리고 엔진은 발전만 하는 차. 구조상 직렬 하이브리드에 큰 배터리를 단 것이다.","chapters":["hybrid"]},
    {"ko":"직렬 하이브리드","en":"Series hybrid","abbr":"","def":"엔진이 발전기만 돌리고 바퀴는 모터가 굴리는 구조. 엔진을 최적 운전점에 둘 수 있지만 에너지를 두 번 변환하는 손실이 있다.","chapters":["hybrid"]},
    {"ko":"병렬 하이브리드","en":"Parallel hybrid","abbr":"","def":"엔진과 모터가 모두 기계적으로 바퀴에 연결되어 힘을 합치는 구조. 모터 위치에 따라 P0부터 P4까지로 부른다.","chapters":["hybrid"]},
    {"ko":"P0~P4","en":"P0–P4 motor positions","abbr":"","def":"병렬 하이브리드에서 모터가 놓이는 자리의 이름. P0은 벨트, P1은 크랭크축, P2는 엔진과 변속기 사이, P3은 변속기 출력, P4는 다른 차축이다.","chapters":["hybrid"]},
    {"ko":"동력 분기","en":"Power split","abbr":"","def":"유성 기어로 엔진 동력을 기계 경로와 전기 경로로 나눠 보내는 직병렬 구조. 대표적으로 엔진을 캐리어, 발전기를 선 기어, 출력을 링 기어에 잇는다.","chapters":["hybrid"]},
    {"ko":"e-CVT","en":"Electronic CVT","abbr":"e-CVT","def":"동력 분기식에서 발전기 회전수를 조절해 엔진 회전수를 차속과 무관하게 정하는 것. 벨트 없이 무단 변속기처럼 동작한다.","chapters":["hybrid"]},
    {"ko":"회생 제동","en":"Regenerative braking","abbr":"","def":"감속할 때 모터를 발전기로 써서 운동 에너지를 전기로 회수하는 제동. 회수량은 모터 출력, 배터리 수용 전력, 구동축 배치가 제한한다.","chapters":["hybrid"]},
    {"ko":"협조 제동","en":"Brake blending","abbr":"","def":"운전자가 요구한 감속도를 회생 제동으로 먼저 채우고 모자란 만큼만 마찰 브레이크로 메우는 제어.","chapters":["hybrid"]},
    {"ko":"아이들 스톱","en":"Idle stop-start","abbr":"ISG","def":"정차 중에 엔진을 끄고 출발할 때 다시 거는 기능. 공회전 연료를 아낀다.","chapters":["hybrid"]},
    {"ko":"애트킨슨 사이클","en":"Atkinson cycle","abbr":"","def":"흡기 밸브를 늦게 닫아 실제 압축비보다 팽창비를 크게 한 사이클. 저속 토크를 잃는 대신 열효율이 높아 하이브리드 엔진에 널리 쓴다.","chapters":["hybrid"]},
    {"ko":"운전점 이동","en":"Load-point shifting","abbr":"","def":"모터로 돕거나 발전 부하를 걸어 엔진을 효율이 좋은 영역에서 일하게 하는 것. 남는 에너지는 배터리에 저장한다.","chapters":["hybrid"]},
    {"ko":"충전 유지 모드","en":"Charge-sustaining mode","abbr":"CS","def":"배터리 SOC를 일정 범위에서 유지하며 달리는 모드. 반대로 전기를 주로 쓰며 SOC를 낮춰 가는 것이 충전 소진(CD) 모드다.","chapters":["hybrid"]},
    {"ko":"등가 연료 소비 최소화","en":"Equivalent consumption minimization strategy","abbr":"ECMS","def":"전기 사용량을 등가 계수로 연료량에 환산해 매 순간 연료와 전기의 합을 최소로 하는 에너지 관리 전략.","chapters":["hybrid"]},
    {"ko":"유틸리티 팩터","en":"Utility factor","abbr":"UF","def":"PHEV 주행 거리 중 전기로만 달린다고 보는 비율. 전기 주행 가능 거리와 하루 주행 거리의 통계 분포에서 정한다.","chapters":["hybrid"]},
    {"ko":"웰 투 휠","en":"Well-to-wheel","abbr":"WtW","def":"연료 채굴이나 발전 단계부터 바퀴까지 전 과정의 에너지 소비와 배출을 따지는 평가 방식.","chapters":["hybrid"]},
    {"ko":"로렌츠 힘","en":"Lorentz force","abbr":"","def":"자기장 안에서 전류가 흐르는 도선이 받는 힘으로 F = B·I·L이다. 모든 전기 모터 토크의 근원이다.","chapters":["motor"]},
    {"ko":"역기전력","en":"Back EMF","abbr":"","def":"모터가 돌면서 스스로 발전해 생기는 전압. 회전 속도에 비례하며 인가 전압을 거스르므로 속도가 높아지면 전류를 밀어 넣기 어려워진다.","chapters":["motor"]},
    {"ko":"회전 자기장","en":"Rotating magnetic field","abbr":"","def":"120°씩 떨어진 세 코일에 120° 위상 차의 3상 전류를 흘리면 합성 자기장이 일정한 크기로 회전하는 것. 교류 모터의 기본 원리다.","chapters":["motor"]},
    {"ko":"동기 속도","en":"Synchronous speed","abbr":"ns","def":"회전 자기장이 도는 속도로 120 × 주파수 ÷ 극수(rpm)다.","chapters":["motor"]},
    {"ko":"영구자석 동기 모터","en":"Permanent magnet synchronous motor","abbr":"PMSM","def":"회전자에 영구자석을 넣어 회전 자기장과 같은 속도로 도는 모터. 효율과 출력 밀도가 높아 전기차의 주류다.","chapters":["motor"]},
    {"ko":"매입형 영구자석 모터","en":"Interior permanent magnet motor","abbr":"IPM","def":"자석을 회전자 철심 안에 묻은 PMSM. 자석 토크에 릴럭턴스 토크가 더해지고 고속에서 자석이 떨어져 나가지 않는다.","chapters":["motor"]},
    {"ko":"릴럭턴스 토크","en":"Reluctance torque","abbr":"","def":"회전자가 자기 저항이 작은 방향으로 정렬하려는 성질에서 생기는 토크. d축과 q축 인덕턴스의 차에 비례한다.","chapters":["motor"]},
    {"ko":"유도 모터","en":"Induction motor","abbr":"IM","def":"회전 자기장이 회전자 도체에 유도한 전류로 토크를 내는 모터. 자석이 필요 없지만 회전자에서도 동손이 생긴다.","chapters":["motor"]},
    {"ko":"슬립(유도 모터)","en":"Slip","abbr":"s","def":"동기 속도와 회전자 속도의 차를 동기 속도로 나눈 값. 슬립이 0이면 유도 전류가 없어 토크도 없다.","chapters":["motor"]},
    {"ko":"기저 속도","en":"Base speed","abbr":"","def":"최대 토크를 낼 수 있는 가장 높은 속도. 이 아래가 정토크 영역, 위가 정출력 영역이다.","chapters":["motor"]},
    {"ko":"약계자 제어","en":"Field weakening","abbr":"","def":"기저 속도 이상에서 자석 자속을 거스르는 d축 전류를 흘려 역기전력을 눌러 속도를 더 올리는 제어. 토크는 속도에 반비례해 줄어든다.","chapters":["motor"]},
    {"ko":"인버터","en":"Inverter","abbr":"","def":"배터리의 직류를 스위치 여섯 개로 잘라 크기와 주파수를 바꿀 수 있는 3상 교류로 만드는 전력 변환기.","chapters":["motor"]},
    {"ko":"IGBT","en":"Insulated-gate bipolar transistor","abbr":"IGBT","def":"고전압·대전류 스위칭에 쓰는 전력 반도체. 인버터의 스위치로 오래 쓰여 왔다.","chapters":["motor"]},
    {"ko":"SiC MOSFET","en":"Silicon carbide MOSFET","abbr":"SiC","def":"탄화규소로 만든 전력 스위치. 스위칭 손실과 도통 손실이 작아 800 V 인버터의 효율을 높인다.","chapters":["motor"]},
    {"ko":"데드타임","en":"Dead time","abbr":"","def":"한 상의 위아래 스위치가 동시에 켜져 단락되지 않도록 둘 다 끄고 기다리는 짧은 시간.","chapters":["motor"]},
    {"ko":"벡터 제어","en":"Field-oriented control","abbr":"FOC","def":"3상 전류를 회전자와 함께 도는 d–q 좌표로 바꿔 자속 성분과 토크 성분을 따로 제어하는 방식.","chapters":["motor"]},
    {"ko":"d–q 축","en":"d–q axes","abbr":"","def":"회전자에 붙어 함께 도는 좌표축. d축은 자석 자속 방향, q축은 그와 전기각 90° 떨어진 토크 방향이다.","chapters":["motor"]},
    {"ko":"MTPA","en":"Maximum torque per ampere","abbr":"MTPA","def":"같은 전류 크기로 가장 큰 토크를 내는 d–q 전류 조합을 따라가는 제어. 동손을 최소로 한다.","chapters":["motor"]},
    {"ko":"레졸버","en":"Resolver","abbr":"","def":"회전자의 절대 각도를 재는 전자기식 센서. 벡터 제어는 회전자 위치를 알아야 하므로 필수다.","chapters":["motor"]},
    {"ko":"헤어핀 권선","en":"Hairpin winding","abbr":"","def":"둥근 선 대신 U자로 굽힌 각형 구리 막대를 슬롯에 꽂는 권선. 슬롯을 꽉 채워 출력 밀도와 방열이 좋아진다.","chapters":["motor"]},
    {"ko":"감속기","en":"Reduction gear","abbr":"","def":"모터의 높은 회전수를 한 단의 고정 기어비(대표적으로 약 9~10:1)로 줄여 바퀴에 전달하는 기어. 모터는 0 rpm부터 최대 토크를 내므로 다단 변속이 필요 없다.","chapters":["motor"]},
    {"ko":"동손과 철손","en":"Copper loss and iron loss","abbr":"","def":"동손은 권선 저항에서 전류의 제곱에 비례해 생기는 열, 철손은 철심에서 자속 변화로 생기는 히스테리시스·와전류 손실이다. 저속 고토크는 동손이, 고속은 철손이 지배한다.","chapters":["motor"]},
    {"ko":"인휠 모터","en":"In-wheel motor","abbr":"","def":"모터를 휠 안에 넣어 바퀴를 직접 굴리는 방식. 구동축이 사라지고 바퀴별 제어가 쉽지만 스프링 아래 질량이 늘어난다.","chapters":["motor"]},
    {"ko":"800 V 시스템","en":"800 V architecture","abbr":"","def":"고전압 계통을 약 800 V로 높인 구조. 같은 출력에서 전류가 절반이 되어 케이블 손실과 무게가 줄고 초급속 충전에 유리하다.","chapters":["motor"]},
    {"ko":"리튬 이온 셀","en":"Lithium-ion cell","abbr":"","def":"리튬 이온이 양극과 음극 사이를 오가며 충·방전하는 이차 전지. 이온은 전해질로, 전자는 외부 회로로 움직인다.","chapters":["battery"]},
    {"ko":"양극","en":"Cathode","abbr":"","def":"방전할 때 리튬 이온을 받아들이는 전극. 재료(NCM, LFP 등)가 셀의 전압과 용량, 가격을 좌우한다.","chapters":["battery"]},
    {"ko":"음극","en":"Anode","abbr":"","def":"충전할 때 리튬 이온을 저장하는 전극. 대부분 흑연을 쓰고 용량을 늘리려 실리콘을 섞는다.","chapters":["battery"]},
    {"ko":"전해질","en":"Electrolyte","abbr":"","def":"양극과 음극 사이에서 리튬 이온만 지나가게 하는 매질. 전자는 통과시키지 않는다.","chapters":["battery"]},
    {"ko":"분리막","en":"Separator","abbr":"","def":"양극과 음극이 직접 닿지 않게 막으면서 이온은 지나가게 하는 다공성 막. 손상되면 내부 단락이 일어난다.","chapters":["battery"]},
    {"ko":"인터칼레이션","en":"Intercalation","abbr":"","def":"리튬 이온이 전극 재료의 결정 구조를 깨지 않고 층 사이로 끼어들어 가는 것. 충·방전을 되풀이할 수 있는 이유다.","chapters":["battery"]},
    {"ko":"NCM","en":"Nickel cobalt manganese oxide","abbr":"NCM","def":"니켈·코발트·망간 산화물 양극재. 에너지 밀도가 높지만 값이 비싸고 열 안정성은 LFP보다 낮다.","chapters":["battery"]},
    {"ko":"LFP","en":"Lithium iron phosphate","abbr":"LFP","def":"리튬 인산철 양극재. 에너지 밀도는 낮지만 싸고 수명이 길며 열적으로 안정하다. 전압 곡선이 평탄해 SOC 추정이 어렵다.","chapters":["battery"]},
    {"ko":"C-rate","en":"C-rate","abbr":"C","def":"용량 대비 충·방전 전류의 크기. 1C는 한 시간에 용량을 모두 쓰는 전류이고 2C는 30분에 쓰는 전류다.","chapters":["battery"]},
    {"ko":"에너지 밀도","en":"Energy density","abbr":"","def":"질량당(Wh/kg) 또는 부피당(Wh/L) 저장하는 에너지. 셀 수준에서 대표적으로 약 150~300 Wh/kg이다.","chapters":["battery"]},
    {"ko":"개방 회로 전압","en":"Open-circuit voltage","abbr":"OCV","def":"전류가 흐르지 않고 충분히 쉰 상태의 셀 전압. SOC의 함수라서 SOC 추정의 기준으로 쓴다.","chapters":["battery"]},
    {"ko":"내부 저항","en":"Internal resistance","abbr":"","def":"셀 안에서 전류의 흐름을 방해하는 저항. 전류에 비례한 전압 강하와 전류의 제곱에 비례한 발열을 만들고 저온에서 크게 늘어난다.","chapters":["battery"]},
    {"ko":"충전 상태","en":"State of charge","abbr":"SOC","def":"현재 남은 전하량을 가용 용량에 대한 백분율로 나타낸 값. 연료 게이지에 해당한다.","chapters":["battery"]},
    {"ko":"건강 상태","en":"State of health","abbr":"SOH","def":"새 배터리 대비 현재 용량(또는 저항)의 비율. 열화의 정도를 나타낸다.","chapters":["battery"]},
    {"ko":"배터리 관리 시스템","en":"Battery management system","abbr":"BMS","def":"셀 전압, 전류, 온도를 감시하고 SOC와 SOH를 추정하며 셀 밸런싱과 보호를 맡는 제어기.","chapters":["battery"]},
    {"ko":"셀 밸런싱","en":"Cell balancing","abbr":"","def":"직렬 셀들의 SOC 차이를 줄이는 것. 가장 높은 셀이 충전을, 가장 낮은 셀이 방전을 끝내 버리므로 맞추지 않으면 팩 용량을 다 쓰지 못한다.","chapters":["battery"]},
    {"ko":"셀 투 팩","en":"Cell-to-pack","abbr":"CTP","def":"모듈 단계를 없애고 셀을 팩에 바로 넣는 구조. 부품과 빈 공간이 줄어 팩 에너지 밀도가 오른다.","chapters":["battery"]},
    {"ko":"열폭주","en":"Thermal runaway","abbr":"","def":"셀 내부 발열 반응이 온도를 올리고 그 온도가 다시 반응을 키우는 연쇄 현상. 한 셀에서 이웃 셀로 번지는 것을 막는 것이 팩 안전 설계의 핵심이다.","chapters":["battery"]},
    {"ko":"리튬 플레이팅","en":"Lithium plating","abbr":"","def":"리튬 이온이 음극 속으로 들어가지 못하고 표면에 금속으로 석출되는 현상. 저온이나 높은 SOC에서 빠르게 충전할 때 생기며 용량 손실과 단락 위험을 부른다.","chapters":["battery"]},
    {"ko":"SEI","en":"Solid electrolyte interphase","abbr":"SEI","def":"음극 표면에 전해질이 분해되어 생기는 얇은 막. 음극을 보호하지만 계속 자라면서 리튬을 소모해 용량이 줄어든다.","chapters":["battery"]},
    {"ko":"정전류–정전압 충전","en":"Constant current–constant voltage charging","abbr":"CC–CV","def":"먼저 일정 전류로 충전하다가 전압이 상한에 닿으면 전압을 유지하며 전류를 줄여 가는 충전 방식.","chapters":["battery"]},
    {"ko":"온보드 차저","en":"On-board charger","abbr":"OBC","def":"완속 충전기의 교류를 직류로 바꿔 배터리를 충전하는 차량 탑재 충전기. 대표적으로 7~11 kW급이다.","chapters":["battery"]},
    {"ko":"급속 충전","en":"DC fast charging","abbr":"DCFC","def":"충전기가 직류를 배터리에 직접 공급하는 충전. SOC가 높아질수록 전류를 줄여야 해서 보통 10→80 % 구간 시간으로 성능을 말한다.","chapters":["battery"]},
    {"ko":"전비","en":"Energy consumption (efficiency)","abbr":"","def":"전기차의 연비에 해당하는 값. km/kWh 또는 Wh/km로 나타내며 승용 전기차는 대표적으로 약 140~200 Wh/km다.","chapters":["battery"]},
    {"ko":"히트 펌프","en":"Heat pump","abbr":"","def":"바깥 공기나 구동계 폐열의 열을 냉매로 퍼 올려 난방하는 장치. 전기 히터보다 같은 전력으로 여러 배의 열을 내 겨울 주행 거리 손실을 줄인다.","chapters":["battery"]},
    {"ko":"프리컨디셔닝","en":"Preconditioning","abbr":"","def":"급속 충전이나 출발 전에 배터리를 적정 온도로 미리 데우거나 식혀 두는 기능.","chapters":["battery"]},
    {"ko":"V2L / V2G","en":"Vehicle-to-load / vehicle-to-grid","abbr":"V2L · V2G","def":"차의 배터리 전력을 바깥 기기에 공급(V2L)하거나 전력망으로 되돌려 보내는(V2G) 기능.","chapters":["battery"]},
    {"ko":"전고체 배터리","en":"Solid-state battery","abbr":"SSB","def":"액체 전해질을 고체로 바꾼 배터리. 안전성과 에너지 밀도 향상이 기대되지만 계면 저항과 양산 공정이 과제다.","chapters":["battery"]},
    {"ko":"SAE 자동화 레벨","en":"SAE levels of driving automation","abbr":"L0–L5","def":"운전 자동화를 0에서 5까지 여섯 단계로 나눈 분류(SAE J3016). 레벨 2까지는 운전자가, 레벨 3부터는 작동 중 시스템이 주행을 책임진다.","chapters":["adas"]},
    {"ko":"운행 설계 영역","en":"Operational design domain","abbr":"ODD","def":"자동화 기능이 작동하도록 설계된 조건의 범위. 도로 종류, 속도, 날씨, 시간대, 지역 등으로 정한다.","chapters":["adas"]},
    {"ko":"어댑티브 크루즈 컨트롤","en":"Adaptive cruise control","abbr":"ACC","def":"앞차가 없으면 설정 속도로, 있으면 설정한 차간 시간을 유지하며 따라가는 종방향 제어 기능.","chapters":["adas"]},
    {"ko":"차간 시간","en":"Time headway","abbr":"THW","def":"앞차와의 거리를 자차 속도로 나눈 값. ACC는 대표적으로 약 1~2.5초 범위에서 설정한다.","chapters":["adas"]},
    {"ko":"자동 긴급 제동","en":"Autonomous emergency braking","abbr":"AEB","def":"충돌이 임박했는데 운전자가 반응하지 않으면 스스로 제동하는 기능.","chapters":["adas"]},
    {"ko":"충돌까지 남은 시간","en":"Time to collision","abbr":"TTC","def":"지금의 상대 속도가 유지될 때 충돌까지 남은 시간으로 상대 거리 ÷ 접근 속도다. 경고와 제동 시점을 정하는 기준이다.","chapters":["adas"]},
    {"ko":"전방 충돌 경고","en":"Forward collision warning","abbr":"FCW","def":"전방 충돌 위험을 소리와 화면, 진동으로 미리 알리는 기능. AEB보다 먼저 작동한다.","chapters":["adas"]},
    {"ko":"차로 이탈 방지 보조","en":"Lane keeping assist","abbr":"LKA","def":"차가 차선을 벗어나려 할 때 조향을 보조해 차로 안으로 되돌리는 기능.","chapters":["adas"]},
    {"ko":"차로 유지 보조","en":"Lane following assist","abbr":"LFA","def":"차로 중앙을 계속 따라가도록 연속적으로 조향을 보조하는 기능. LKA가 경계에서 개입하는 것과 달리 항상 중앙을 추종한다.","chapters":["adas"]},
    {"ko":"후측방 경고","en":"Blind-spot detection","abbr":"BSD","def":"사이드미러에 보이지 않는 옆 차로 뒤쪽의 차량을 레이더로 감지해 알리는 기능.","chapters":["adas"]},
    {"ko":"운전자 모니터링 시스템","en":"Driver monitoring system","abbr":"DMS","def":"실내 카메라로 시선과 눈꺼풀, 고개 움직임을 추적해 졸음과 부주의를 판단하는 시스템.","chapters":["adas"]},
    {"ko":"스트링 안정성","en":"String stability","abbr":"","def":"줄지어 달리는 차들에서 앞차의 속도 변화가 뒤로 갈수록 커지지 않고 줄어드는 성질. 깨지면 유령 정체가 생긴다.","chapters":["adas"]},
    {"ko":"제어권 전환","en":"Takeover request","abbr":"TOR","def":"자동화 시스템이 한계에 닿았을 때 운전자에게 운전을 넘겨받으라고 요구하는 것.","chapters":["adas"]},
    {"ko":"핀홀 카메라 모델","en":"Pinhole camera model","abbr":"","def":"3차원 점이 바늘구멍을 지나 영상 평면에 맺히는 것으로 본 투영 모델. 영상 좌표는 초점 거리 × X ÷ Z로 거리에 반비례한다.","chapters":["sensors"]},
    {"ko":"화각","en":"Field of view","abbr":"FOV","def":"센서가 한 번에 볼 수 있는 각도 범위. 카메라는 초점 거리가 짧을수록 화각이 넓고 먼 물체는 작게 찍힌다.","chapters":["sensors"]},
    {"ko":"각 분해능","en":"Angular resolution","abbr":"","def":"센서가 구분할 수 있는 가장 작은 각도 차. 같은 각 분해능이라도 멀어질수록 물체에 닿는 픽셀이나 점의 수는 급격히 준다.","chapters":["sensors"]},
    {"ko":"스테레오 시차","en":"Stereo disparity","abbr":"d","def":"두 카메라 영상에서 같은 점이 찍힌 위치의 차. 거리는 초점 거리 × 베이스라인 ÷ 시차이며 거리 오차는 거리의 제곱에 비례해 커진다.","chapters":["sensors"]},
    {"ko":"레이더","en":"Radar","abbr":"","def":"전파를 쏘고 반사파를 받아 거리와 상대 속도를 재는 센서. 차량용은 77 GHz 대역을 쓰며 비·안개·어둠에 강하다.","chapters":["sensors"]},
    {"ko":"FMCW","en":"Frequency-modulated continuous wave","abbr":"FMCW","def":"주파수가 시간에 따라 직선으로 변하는 연속파를 쓰는 방식. 송신파와 수신파의 주파수 차로 거리를 구한다.","chapters":["sensors"]},
    {"ko":"처프","en":"Chirp","abbr":"","def":"주파수가 일정한 기울기로 올라가는(또는 내려가는) 신호 한 구간. FMCW 레이더의 기본 파형이다.","chapters":["sensors"]},
    {"ko":"비트 주파수","en":"Beat frequency","abbr":"","def":"송신 처프와 지연된 수신 처프를 섞었을 때 나오는 주파수 차. 타깃까지의 거리에 비례한다.","chapters":["sensors"]},
    {"ko":"도플러 효과","en":"Doppler effect","abbr":"","def":"움직이는 물체에서 반사된 파의 주파수가 상대 속도에 비례해 달라지는 현상. 레이더가 속도를 직접 재는 원리다.","chapters":["sensors"]},
    {"ko":"거리 분해능","en":"Range resolution","abbr":"","def":"거리가 다른 두 타깃을 구분할 수 있는 최소 간격. 레이더에서는 c/(2B)로 대역폭 B가 넓을수록 좋아진다.","chapters":["sensors"]},
    {"ko":"4D 이미징 레이더","en":"4D imaging radar","abbr":"","def":"많은 안테나 채널로 거리, 방위각, 속도에 더해 높이(고도각)까지 구분하는 고해상도 레이더.","chapters":["sensors"]},
    {"ko":"라이다","en":"LiDAR","abbr":"","def":"레이저 펄스를 쏘아 돌아오는 시간으로 거리를 재고 주변을 3차원 점들로 스캔하는 센서.","chapters":["sensors"]},
    {"ko":"비행 시간법","en":"Time of flight","abbr":"ToF","def":"빛이나 소리가 갔다 돌아오는 시간으로 거리를 구하는 방식. 거리 = 속도 × 왕복 시간 ÷ 2다.","chapters":["sensors"]},
    {"ko":"포인트 클라우드","en":"Point cloud","abbr":"","def":"라이다가 잰 3차원 점들의 집합. 각 점은 위치와 반사 강도를 가진다.","chapters":["sensors"]},
    {"ko":"초음파 센서","en":"Ultrasonic sensor","abbr":"","def":"초음파의 왕복 시간으로 수 m 이내의 근거리를 재는 센서. 음속이 약 343 m/s로 느려 주차 보조에 알맞다.","chapters":["sensors"]},
    {"ko":"GNSS","en":"Global navigation satellite system","abbr":"GNSS","def":"위성 네 개 이상까지의 의사 거리로 위치와 시각을 구하는 위성 항법 시스템. GPS, 갈릴레오 등을 통틀어 부른다.","chapters":["sensors"]},
    {"ko":"RTK","en":"Real-time kinematic","abbr":"RTK","def":"기준국의 보정 정보와 반송파 위상을 써서 cm급 위치를 얻는 GNSS 기법.","chapters":["sensors"]},
    {"ko":"관성 측정 장치","en":"Inertial measurement unit","abbr":"IMU","def":"3축 가속도계와 3축 자이로로 가속도와 각속도를 재는 센서. 적분하면 자세와 위치를 얻지만 오차가 시간에 따라 누적(드리프트)된다.","chapters":["sensors"]},
    {"ko":"휠 오도메트리","en":"Wheel odometry","abbr":"","def":"바퀴 회전수와 조향각으로 이동 거리와 방향을 추정하는 것. 미끄러짐과 타이어 반지름 오차가 쌓인다.","chapters":["sensors"]},
    {"ko":"캘리브레이션","en":"Calibration","abbr":"","def":"센서의 내부 파라미터(초점 거리, 왜곡)와 외부 파라미터(차체에 대한 위치와 자세)를 구하는 작업. 틀어지면 센서 융합이 어긋난다.","chapters":["sensors"]},
    {"ko":"객체 검출","en":"Object detection","abbr":"","def":"영상이나 포인트 클라우드에서 차량, 보행자 같은 물체의 위치와 종류를 찾아내는 것.","chapters":["perception"]},
    {"ko":"바운딩 박스","en":"Bounding box","abbr":"","def":"검출한 물체를 둘러싼 직사각형(3D에서는 직육면체). 위치, 크기, 방향과 클래스, 신뢰도 점수를 함께 가진다.","chapters":["perception"]},
    {"ko":"합성곱 신경망","en":"Convolutional neural network","abbr":"CNN","def":"작은 필터를 영상 전체에 미끄러뜨리며 특징을 뽑는 층을 여러 겹 쌓은 신경망. 앞층은 모서리, 뒤층은 물체 수준의 특징을 본다.","chapters":["perception"]},
    {"ko":"IoU","en":"Intersection over union","abbr":"IoU","def":"두 박스가 겹친 넓이를 두 박스를 합친 넓이로 나눈 값. 예측이 정답과 얼마나 맞는지 재는 기준이다.","chapters":["perception"]},
    {"ko":"비최대 억제","en":"Non-maximum suppression","abbr":"NMS","def":"같은 물체에 겹쳐 나온 여러 후보 박스 중 점수가 가장 높은 것만 남기고 나머지를 지우는 후처리.","chapters":["perception"]},
    {"ko":"의미 분할","en":"Semantic segmentation","abbr":"","def":"영상의 모든 픽셀에 도로, 차선, 차량, 보행자 같은 클래스를 매기는 것.","chapters":["perception"]},
    {"ko":"정밀도","en":"Precision","abbr":"","def":"검출했다고 한 것 중 실제로 맞은 비율. 낮으면 오검출(FP)이 많아 불필요한 제동이 생긴다.","chapters":["perception"]},
    {"ko":"재현율","en":"Recall","abbr":"","def":"실제로 있는 물체 중 검출해 낸 비율. 낮으면 미검출(FN)이 많아 물체를 놓친다.","chapters":["perception"]},
    {"ko":"mAP","en":"Mean average precision","abbr":"mAP","def":"정밀도–재현율 곡선 아래 넓이(AP)를 클래스별로 구해 평균한 검출 성능 지표.","chapters":["perception"]},
    {"ko":"조감도 표현","en":"Bird's-eye view","abbr":"BEV","def":"여러 센서의 정보를 위에서 내려다본 평면 격자로 모은 표현. 거리와 크기가 왜곡되지 않아 융합과 계획에 편하다.","chapters":["perception"]},
    {"ko":"점유 격자","en":"Occupancy grid","abbr":"","def":"주변 공간을 격자로 나누고 칸마다 무언가 차지하고 있을 확률을 저장한 지도. 관측이 들어올 때마다 로그 오즈를 더해 갱신한다.","chapters":["perception"]},
    {"ko":"칼만 필터","en":"Kalman filter","abbr":"KF","def":"운동 모델로 예측하고 잡음 있는 측정으로 갱신하는 것을 반복해 상태와 그 불확실성을 추정하는 필터.","chapters":["perception"]},
    {"ko":"데이터 연관","en":"Data association","abbr":"","def":"새로 들어온 검출이 기존에 추적하던 어느 물체에 해당하는지 짝짓는 문제.","chapters":["perception"]},
    {"ko":"센서 융합","en":"Sensor fusion","abbr":"","def":"여러 센서의 정보를 합쳐 하나보다 정확하고 견고한 추정을 얻는 것. 원시 데이터, 특징, 객체 단계에서 합치는 초기·중기·후기 융합이 있다.","chapters":["perception"]},
    {"ko":"측위","en":"Localization","abbr":"","def":"차가 지도 위 어디에 어떤 자세로 있는지 추정하는 것. 차로 수준의 판단에는 수십 cm 이하의 정확도가 필요하다.","chapters":["perception"]},
    {"ko":"정밀 지도","en":"High-definition map","abbr":"HD map","def":"차선, 정지선, 신호등, 표지의 위치를 cm급 정확도로 담은 지도. 센서가 보지 못하는 곳의 사전 정보를 준다.","chapters":["perception"]},
    {"ko":"파티클 필터","en":"Particle filter","abbr":"","def":"가능한 상태를 수많은 입자로 뿌리고 관측과 잘 맞는 입자에 가중치를 주어 다시 뽑는 추정 기법. 분포가 여러 봉우리여도 다룰 수 있다.","chapters":["perception"]},
    {"ko":"ICP","en":"Iterative closest point","abbr":"ICP","def":"두 포인트 클라우드에서 가장 가까운 점끼리 짝지어 오차가 최소가 되는 회전과 이동을 반복해 찾는 정합 알고리즘.","chapters":["perception"]},
    {"ko":"SLAM","en":"Simultaneous localization and mapping","abbr":"SLAM","def":"지도가 없는 곳에서 지도를 만들면서 동시에 그 지도 안의 자기 위치를 추정하는 기술.","chapters":["perception"]},
    {"ko":"롱테일","en":"Long tail","abbr":"","def":"하나하나는 매우 드물지만 종류가 끝없이 많은 예외 상황들. 학습 데이터에 거의 없어 자율주행의 가장 어려운 문제로 꼽힌다.","chapters":["perception"]},
    {"ko":"예측","en":"Prediction","abbr":"","def":"주변 차량과 보행자가 앞으로 몇 초 동안 어떻게 움직일지 추정하는 것. 여러 가능성을 확률과 함께 내놓는다.","chapters":["planning"]},
    {"ko":"경로 계획","en":"Path planning","abbr":"","def":"출발지에서 목적지까지, 또는 현재 위치에서 몇 초 앞까지 차가 따라갈 길을 정하는 것. 전역 경로, 행동 결정, 지역 궤적의 계층으로 나눈다.","chapters":["planning"]},
    {"ko":"궤적","en":"Trajectory","abbr":"","def":"위치뿐 아니라 각 지점을 언제 지나는지(속도 프로파일)까지 정한 경로.","chapters":["planning"]},
    {"ko":"A*","en":"A-star search","abbr":"A*","def":"지금까지의 비용과 목표까지의 추정 비용(휴리스틱)의 합이 작은 노드부터 펼치는 최단 경로 탐색 알고리즘.","chapters":["planning"]},
    {"ko":"하이브리드 A*","en":"Hybrid A*","abbr":"","def":"차의 조향 기구학을 지키는 연속 상태로 A*를 확장한 탐색. 주차처럼 좁은 공간에서 전진과 후진을 섞은 경로를 찾는다.","chapters":["planning"]},
    {"ko":"유한 상태 기계","en":"Finite state machine","abbr":"FSM","def":"차로 유지, 차로 변경, 정지 같은 상태와 그 사이의 전환 조건으로 행동 결정을 나타낸 모델.","chapters":["planning"]},
    {"ko":"프레네 좌표","en":"Frenet frame","abbr":"","def":"기준 경로를 따라간 거리 s와 경로에서 옆으로 벗어난 거리 d로 위치를 나타내는 좌표계. 굽은 도로에서도 종·횡 계획을 따로 다룰 수 있다.","chapters":["planning"]},
    {"ko":"저크","en":"Jerk","abbr":"","def":"가속도의 시간 변화율(m/s³). 승차감의 척도이므로 궤적을 만들 때 최소화하는 비용 항으로 쓴다.","chapters":["planning"]},
    {"ko":"퓨어 퍼슈트","en":"Pure pursuit","abbr":"","def":"전방 주시 거리만큼 앞의 경로 위 점을 목표로 삼아, 그 점을 지나는 원호의 곡률로 조향하는 기하학적 경로 추종 방법.","chapters":["planning"]},
    {"ko":"전방 주시 거리","en":"Lookahead distance","abbr":"Ld","def":"경로 추종에서 목표점을 잡는 앞쪽 거리. 짧으면 민감하게 따라가지만 진동하고, 길면 부드럽지만 코너를 안쪽으로 가로지른다.","chapters":["planning"]},
    {"ko":"스탠리 제어기","en":"Stanley controller","abbr":"","def":"앞 차축 기준의 방향 오차와 횡 오차 항을 더해 조향각을 정하는 경로 추종 방법.","chapters":["planning"]},
    {"ko":"LQR","en":"Linear quadratic regulator","abbr":"LQR","def":"선형 모델에서 상태 오차와 입력 크기의 제곱 합을 최소로 하는 최적 상태 피드백 제어기.","chapters":["planning"]},
    {"ko":"모델 예측 제어","en":"Model predictive control","abbr":"MPC","def":"차량 모델로 앞으로 몇 초의 거동을 예측해 제약 조건 아래 최적 입력 열을 구하고, 첫 입력만 쓴 뒤 매 주기 다시 푸는 제어.","chapters":["planning"]},
    {"ko":"엔드투엔드 학습","en":"End-to-end learning","abbr":"E2E","def":"센서 입력에서 주행 궤적이나 제어 명령까지를 하나의 신경망으로 학습하는 접근. 모듈 사이의 정보 손실이 없지만 왜 그렇게 판단했는지 해석하기 어렵다.","chapters":["autonomy"]},
    {"ko":"모방 학습","en":"Imitation learning","abbr":"","def":"사람 운전 데이터를 정답 삼아 같은 상황에서 같은 행동을 내도록 학습하는 것.","chapters":["autonomy"]},
    {"ko":"섀도 모드","en":"Shadow mode","abbr":"","def":"시스템이 실제 제어는 하지 않고 뒤에서 판단만 내려, 사람의 운전과 달랐던 사례를 수집하는 운용 방식.","chapters":["autonomy"]},
    {"ko":"최소 위험 기동","en":"Minimal risk maneuver","abbr":"MRM","def":"시스템이 더는 주행을 계속할 수 없을 때 스스로 감속하거나 갓길에 세워 위험이 가장 작은 상태로 가는 동작.","chapters":["autonomy"]},
    {"ko":"기능 안전","en":"Functional safety (ISO 26262)","abbr":"FuSa","def":"전기·전자 시스템의 고장으로 생기는 위험을 받아들일 수 있는 수준으로 낮추는 체계. 자동차 분야 표준이 ISO 26262다.","chapters":["autonomy"]},
    {"ko":"ASIL","en":"Automotive safety integrity level","abbr":"ASIL","def":"위험원의 심각도(S), 노출 빈도(E), 제어 가능성(C)으로 정하는 안전 무결성 등급. QM과 A~D가 있으며 D가 가장 엄격하다.","chapters":["autonomy"]},
    {"ko":"페일 세이프","en":"Fail-safe","abbr":"","def":"고장이 나면 기능을 끄고 안전한 상태로 가는 설계. 운전자가 넘겨받을 수 있을 때 통한다.","chapters":["autonomy"]},
    {"ko":"페일 오퍼레이셔널","en":"Fail-operational","abbr":"","def":"고장이 나도 일정 시간 기능을 유지하는 설계. 넘겨받을 운전자가 없는 레벨 4 이상에서 필요하다.","chapters":["autonomy"]},
    {"ko":"이중화","en":"Redundancy","abbr":"","def":"같은 기능을 독립된 둘 이상의 채널로 갖추는 것. 조향, 제동, 전원, 컴퓨터, 통신에 적용한다.","chapters":["autonomy"]},
    {"ko":"공통 원인 고장","en":"Common-cause failure","abbr":"CCF","def":"하나의 원인이 이중화한 채널을 한꺼번에 무너뜨리는 고장. 같은 전원, 같은 소프트웨어 결함, 같은 환경 조건이 대표적 원인이다.","chapters":["autonomy"]},
    {"ko":"SOTIF","en":"Safety of the intended functionality (ISO 21448)","abbr":"SOTIF","def":"고장이 없어도 센서와 알고리즘의 성능 한계나 예측 가능한 오용 때문에 생기는 위험을 다루는 안전 체계.","chapters":["autonomy"]},
    {"ko":"책임 민감 안전","en":"Responsibility-sensitive safety","abbr":"RSS","def":"앞차가 최대로 제동해도 반응 시간 뒤 제동해 추돌하지 않는 최소 안전 거리처럼, 안전 운전의 상식을 수식으로 정식화한 모델.","chapters":["autonomy"]},
    {"ko":"개입","en":"Disengagement","abbr":"","def":"자율주행 중 안전 요원이나 시스템이 자동 운전을 해제하는 사건. 개입당 주행 거리는 조건과 기준이 제각각이라 회사끼리 비교하기 어렵다.","chapters":["autonomy"]},
    {"ko":"V2X","en":"Vehicle-to-everything","abbr":"V2X","def":"차가 다른 차, 신호등 같은 인프라, 보행자, 네트워크와 주고받는 통신. 센서 시야 밖의 정보를 얻을 수 있다.","chapters":["autonomy"]},
    {"ko":"C-V2X","en":"Cellular V2X","abbr":"C-V2X","def":"이동통신 기술을 바탕으로 한 V2X 규격. 기지국을 거치는 방식과 단말끼리 직접 통신하는 방식을 함께 쓴다.","chapters":["autonomy"]},
    {"ko":"군집 주행","en":"Platooning","abbr":"","def":"여러 대가 통신으로 가감속을 맞추며 짧은 차간 거리로 줄지어 달리는 것. 공기 저항과 도로 점유를 줄인다.","chapters":["autonomy"]},
    {"ko":"시나리오 기반 시험","en":"Scenario-based testing","abbr":"","def":"실도로 주행 거리 대신 끼어들기, 무단횡단 같은 상황을 변수화해 체계적으로 시험하는 검증 방법.","chapters":["autonomy"]},
    {"ko":"디지털 트윈","en":"Digital twin","abbr":"","def":"실제 도로와 차량, 센서를 가상 환경에 그대로 옮긴 모델. 위험하거나 드문 상황을 시뮬레이션으로 되풀이해 시험한다.","chapters":["autonomy"]},
  ]
};
